import React, { useEffect, useRef, useMemo } from 'react';
import * as THREE from 'three';
import { SystemStatus } from '../types';

interface SceneProps {
  status: SystemStatus;
  audioVolume: number;
}

// --- GLSL SHADERS ---

const vertexShader = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uIntensity;
  varying vec2 vUv;

  void main() {
    vec2 uv = vUv;

    // Create fluid distortion
    for(float i = 1.0; i < 4.0; i++){
        uv.x += 0.6 / i * cos(i * 2.5 * uv.y + uTime * 0.5);
        uv.y += 0.6 / i * cos(i * 1.5 * uv.x + uTime * 0.5);
    }

    // Mix colors based on distorted UVs
    float strength = 0.5 + 0.5 * sin(uv.x * 10.0 + uTime);
    vec3 color = mix(uColorA, uColorB, strength * uIntensity);

    // Vignette
    float dist = distance(vUv, vec2(0.5));
    color *= 1.0 - dist * 0.8;

    gl_FragColor = vec4(color, 1.0);
  }
`;

const Scene: React.FC<SceneProps> = ({ status, audioVolume }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const backgroundMaterialRef = useRef<THREE.ShaderMaterial | null>(null);

  const roboEchoRef = useRef<THREE.Mesh | null>(null);
  const roboVigilRef = useRef<THREE.Mesh | null>(null);

  // Data Tunnel Particles
  const particlesRef = useRef<THREE.Points | null>(null);

  const animationFrameRef = useRef<number>(0);

  // Target colors for interpolation
  const colors = useMemo(() => ({
    optimal: {
      a: new THREE.Color('#0c0018'), // Deep Dark Blue
      b: new THREE.Color('#5a47e7')  // Echo Blue
    },
    threat: {
      a: new THREE.Color('#1a0000'), // Deep Dark Red
      b: new THREE.Color('#ff0000')  // Vigil Red
    }
  }), []);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 18;
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // --- FLUID BACKGROUND ---
    const bgGeometry = new THREE.PlaneGeometry(100, 100);
    const bgMaterial = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(colors.optimal.a) },
        uColorB: { value: new THREE.Color(colors.optimal.b) },
        uIntensity: { value: 0.5 }
      },
      depthWrite: false, 
    });
    const backgroundMesh = new THREE.Mesh(bgGeometry, bgMaterial);
    backgroundMesh.position.z = -20; // Push back further
    scene.add(backgroundMesh);
    backgroundMaterialRef.current = bgMaterial;

    // --- LIGHTING ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);
    const dirLight1 = new THREE.DirectionalLight(0xffffff, 2);
    dirLight1.position.set(5, 5, 5);
    scene.add(dirLight1);
    const pointLight = new THREE.PointLight(0x5a47e7, 5, 50);
    pointLight.position.set(0, 0, 5);
    scene.add(pointLight);

    // --- ECHO (LIQUID ROBOT) ---
    const echoGeom = new THREE.SphereGeometry(3, 64, 64); 
    const echoMat = new THREE.MeshPhysicalMaterial({
      color: 0xffffff,
      roughness: 0.1,
      metalness: 0.2,
      transmission: 0.9,
      thickness: 2.0,
      ior: 1.5,
      emissive: 0x5a47e7,
      emissiveIntensity: 0.4
    });
    const roboEcho = new THREE.Mesh(echoGeom, echoMat);
    scene.add(roboEcho);
    roboEchoRef.current = roboEcho;

    // --- VIGIL (THREAT ROBOT - HYPER GEOMETRY) ---
    const vigilGeom = new THREE.IcosahedronGeometry(3.5, 1);
    const vigilMat = new THREE.MeshStandardMaterial({ 
      color: 0x000000, 
      emissive: 0xff0000,
      emissiveIntensity: 3,
      wireframe: true,
      roughness: 0.2,
      metalness: 1.0
    });
    const roboVigil = new THREE.Mesh(vigilGeom, vigilMat);
    roboVigil.visible = false;
    scene.add(roboVigil);
    roboVigilRef.current = roboVigil;

    // --- DATA TUNNEL PARTICLES ---
    const pCount = 2000;
    const pGeo = new THREE.BufferGeometry();
    const pPos = new Float32Array(pCount * 3);

    // Create a tunnel shape
    for(let i=0; i<pCount; i++) {
       pPos[i*3] = (Math.random() - 0.5) * 100; // x
       pPos[i*3+1] = (Math.random() - 0.5) * 100; // y
       pPos[i*3+2] = Math.random() * 100 - 50; // z
    }
    pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));

    const pMat = new THREE.PointsMaterial({
        color: 0x5a47e7,
        size: 0.2,
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending
    });
    const particles = new THREE.Points(pGeo, pMat);
    scene.add(particles);
    particlesRef.current = particles;

    // --- RESIZE ---
    const handleResize = () => {
      if (cameraRef.current && rendererRef.current) {
        cameraRef.current.aspect = window.innerWidth / window.innerHeight;
        cameraRef.current.updateProjectionMatrix();
        rendererRef.current.setSize(window.innerWidth, window.innerHeight);
      }
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      if (mountRef.current && rendererRef.current) {
        mountRef.current.removeChild(rendererRef.current.domElement);
      }
      renderer.dispose();
    };
  }, [colors]);

  // --- ANIMATION LOOP ---
  useEffect(() => {
    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);

      const time = Date.now() * 0.001;
      const isThreat = status === SystemStatus.THREAT_DETECTED;
      const volRatio = Math.min(audioVolume / 200, 1.0); 

      // 1. FLUID BACKGROUND
      if (backgroundMaterialRef.current) {
        const uniforms = backgroundMaterialRef.current.uniforms;
        uniforms.uTime.value += 0.005 + (volRatio * 0.02);
        const targetA = isThreat ? colors.threat.a : colors.optimal.a;
        const targetB = isThreat ? colors.threat.b : colors.optimal.b;
        uniforms.uColorA.value.lerp(targetA, 0.05);
        uniforms.uColorB.value.lerp(targetB, 0.05);
      }

      // 2. DATA TUNNEL (WARP SPEED EFFECT)
      if (particlesRef.current) {
          const positions = particlesRef.current.geometry.attributes.position.array as Float32Array;
          const speed = isThreat ? 2.5 : 0.1; // Massive speed boost on threat

          for(let i=0; i < positions.length / 3; i++) {
              positions[i*3+2] += speed; // Move towards camera (Z+)

              // Reset if past camera
              if (positions[i*3+2] > 20) {
                  positions[i*3+2] = -80;
                  // Randomize XY slightly on reset for variety
                  positions[i*3] = (Math.random() - 0.5) * 100;
                  positions[i*3+1] = (Math.random() - 0.5) * 100;
              }
          }
          particlesRef.current.geometry.attributes.position.needsUpdate = true;

          // Color Switch
          const pMat = particlesRef.current.material as THREE.PointsMaterial;
          const targetColor = isThreat ? new THREE.Color(0xff0000) : new THREE.Color(0x5a47e7);
          pMat.color.lerp(targetColor, 0.1);
      }

      // 3. ECHO ANIMATION (ENHANCED)
      if (roboEchoRef.current) {
        roboEchoRef.current.visible = !isThreat;
        if (!isThreat) {
          // Organic breathing motion: multiple sine waves for non-linear movement
          const breath = Math.sin(time * 1.5) * 0.03 + Math.sin(time * 2.5) * 0.02;

          // Scale: Base size + breath + audio reactivity
          const scale = 1.0 + breath + (volRatio * 0.4);
          roboEchoRef.current.scale.setScalar(scale);

          // Rotation: Slow steady turn + slight floating tilt
          roboEchoRef.current.rotation.y = time * 0.2;
          roboEchoRef.current.rotation.z = Math.sin(time * 0.5) * 0.05;

          // Emissive: Rhythmic pulsating glow (heartbeat) + audio reactivity
          const material = roboEchoRef.current.material as THREE.MeshPhysicalMaterial;

          if (status === SystemStatus.OPTIMAL) {
            // Subtle breathing pulse for emissive intensity when OPTIMAL
            const pulse = 0.4 + (Math.sin(time * 1.2) * 0.15); 
            // Blend pulse with high audio reactivity
            material.emissiveIntensity = pulse + (volRatio * 5.0);

            // Subtle color shift towards white/light blue based on volume
            material.emissive.lerpColors(
                new THREE.Color(0x5a47e7), 
                new THREE.Color(0xffffff), 
                volRatio * 0.5
            );
          } else {
            // Default behavior for other non-threat states
            material.emissiveIntensity = 0.4 + (volRatio * 3.0);
            material.emissive.set(0x5a47e7);
          }
        }
      }

      // 4. VIGIL ANIMATION (The "Impossible Calculation" Look)
      if (roboVigilRef.current) {
        roboVigilRef.current.visible = isThreat;
        if (isThreat) {
           // Rapid erratic rotation simulating intense calculation
           roboVigilRef.current.rotation.x += 0.2;
           roboVigilRef.current.rotation.y += 0.3;

           // Pulse size
           const pulse = 1 + Math.sin(time * 20) * 0.2 + volRatio;
           roboVigilRef.current.scale.setScalar(pulse);

           // Glitch shake
           roboVigilRef.current.position.x = (Math.random() - 0.5) * 0.5;
           roboVigilRef.current.position.y = (Math.random() - 0.5) * 0.5;
        }
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();

    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [status, audioVolume, colors]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default Scene;

