    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const bgGeometry = new THREE.PlaneGeometry(100, 100);
    const bgMaterial = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(colors.optimal.a) },
        uColorB: { value: new THREE.Color(colors.optimal.b) },
        uIntensity: { value: 0.5 }
      },
      depthWrite: false, 
    });
    const backgroundMesh = new THREE.Mesh(bgGeometry, bgMaterial);
    backgroundMesh.position.z = -20;
    scene.add(backgroundMesh);
    backgroundMaterialRef.current = bgMaterial;

    // --- LIGHTING ---
    scene.add(new THREE.AmbientLight(0xffffff, 0.4));
    const pointLight = new THREE.PointLight(0x5a47e7, 10, 60);
    pointLight.position.set(0, 0, 10);
    scene.add(pointLight);

    // --- ECHO (ENHANCED ENERGY CORE) ---
    const echoGroup = new THREE.Group();

    // Core (Inner)
    const coreGeom = new THREE.SphereGeometry(2.2, 64, 64);
    const coreMat = new THREE.MeshPhysicalMaterial({
      color: 0x5a47e7,
      emissive: 0x5a47e7,
      emissiveIntensity: 2,
      roughness: 0,
      metalness: 1,
      transparent: true,
      opacity: 0.8
    });
