      wireframe: true,
      transparent: true,
      opacity: 0.3
    });
    const vigilWire = new THREE.Mesh(vigilWireGeom, vigilWireMat);
    vigilGroup.add(vigilWire);

    vigilGroup.visible = false;
    scene.add(vigilGroup);
    roboVigilGroupRef.current = vigilGroup;

    // --- PARTICLES ---
    const pCount = 3000;
    const pGeo = new THREE.BufferGeometry();
