          // Complex breathing & floating idle
          const breath = Math.sin(time * 1.5) * 0.05 + Math.sin(time * 3.0) * 0.02;
          const floatY = Math.sin(time * 0.8) * 0.3;

          const scale = 1.0 + breath + (volRatio * 0.6);
