               const speedFactor = (i + 1) * 0.01;
               ring.rotation.x += speedFactor + (volRatio * 0.06);
               ring.rotation.z += speedFactor * 0.5;

               const ringMat = (ring as THREE.Mesh).material as THREE.MeshBasicMaterial;
               ringMat.opacity = 0.2 + (volRatio * 0.8) + (Math.sin(time * 4) * 0.1);
            });
          }
        }
      }

      // VIGIL ANIMATION (Refined)
      if (roboVigilGroupRef.current) {
        roboVigilGroupRef.current.visible = isThreat;
        if (isThreat) {
           // Aggressive erratic glitching
           const glitchTrigger = Math.random() > 0.95;
           const shakeIntensity = glitchTrigger ? 0.8 : 0.1;
           const shakeX = (Math.random() - 0.5) * shakeIntensity;
           const shakeY = (Math.random() - 0.5) * shakeIntensity;

           roboVigilGroupRef.current.position.set(shakeX, shakeY, 0);

           // Core animation
           const core = roboVigilGroupRef.current.children[0] as THREE.Mesh;
           const coreMat = core.material as THREE.MeshStandardMaterial;

           // Aggressive pulsing emissive
           const pulseSpeed = 15 + (volRatio * 10);
           const basePulse = 5 + Math.sin(time * pulseSpeed) * 3;
           const glitchPulse = glitchTrigger ? 20 : 0;
           coreMat.emissiveIntensity = basePulse + glitchPulse + (volRatio * 20);

           // Jitter core scale
           const coreScale = 1.0 + (Math.random() * 0.1) + (volRatio * 0.3);
           core.scale.setScalar(coreScale);
           core.rotation.x += 0.1;
           core.rotation.y += 0.15;

           // Shell (Wireframe) Glitch
           const shell = roboVigilGroupRef.current.children[1] as THREE.Mesh;

           // Stepped rotation (looks like a digital glitch)
           if (glitchTrigger || Math.random() > 0.9) {
             shell.rotation.x += Math.PI * 0.25 * (Math.random() > 0.5 ? 1 : -1);
             shell.rotation.y += Math.PI * 0.1 * Math.random();
           } else {
             shell.rotation.x += 0.02;
             shell.rotation.y += 0.03;
           }

           // Intense scale jitter for the wireframe shell
           const shellPulse = 1.0 + (glitchTrigger ? 0.3 : 0.05) + (Math.sin(time * 25) * 0.05) + (volRatio * 0.4);
           shell.scale.setScalar(shellPulse);

           // Visibility flickers on glitch
           if (glitchTrigger && Math.random() > 0.5) {
             shell.visible = false;
             setTimeout(() => { if (roboVigilGroupRef.current) shell.visible = true; }, 50);
           }
        }
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [status, audioVolume, colors]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

