const HexStream = ({ colorClass = "text-red-500" }: { colorClass?: string }) => {
  const [lines, setLines] = useState<string[]>([]);

  useEffect(() => {
    const chars = "01 04 A1 FF 4D C2 99 8B 12 55";
    const interval = setInterval(() => {
      setLines(prev => {
        const newLine = chars.split(' ').sort(() => 0.5 - Math.random()).join(' ');
        const newLines = [newLine, ...prev];
        return newLines.slice(0, 20);
      });
    }, 50); 
    return () => clearInterval(interval);
  }, []);

  return (
    <div className={`font-mono text-[10px] opacity-40 leading-tight ${colorClass} overflow-hidden h-full whitespace-pre-wrap`}>
      {lines.map((line, i) => (
        <div key={i} style={{ opacity: 1 - i * 0.05 }}>{line}</div>
      ))}
    </div>
  );
};

