// --- GLSL SHADERS ---

const vertexShader = `
  varying vec2 vUv;
  varying vec3 vPosition;
  varying vec3 vNormal;
  void main() {
    vUv = uv;
    vPosition = position;
    vNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uIntensity;
  varying vec2 vUv;

  void main() {
    vec2 uv = vUv;

    for(float i = 1.0; i < 4.0; i++){
        uv.x += 0.6 / i * cos(i * 2.5 * uv.y + uTime * 0.5);
        uv.y += 0.6 / i * cos(i * 1.5 * uv.x + uTime * 0.5);
    }

    float strength = 0.5 + 0.5 * sin(uv.x * 10.0 + uTime);
    vec3 color = mix(uColorA, uColorB, strength * uIntensity);

    float dist = distance(vUv, vec2(0.5));
    color *= 1.0 - dist * 0.8;

    gl_FragColor = vec4(color, 1.0);
  }
`;

const Scene: React.FC<SceneProps> = ({ status, audioVolume }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const backgroundMaterialRef = useRef<THREE.ShaderMaterial | null>(null);

  const roboEchoGroupRef = useRef<THREE.Group | null>(null);
  const roboVigilGroupRef = useRef<THREE.Group | null>(null);
  const ringsRef = useRef<THREE.Group | null>(null);

  const particlesRef = useRef<THREE.Points | null>(null);
  const animationFrameRef = useRef<number>(0);

  const colors = useMemo(() => ({
    optimal: {
      a: new THREE.Color('#0c0018'),
      b: new THREE.Color('#5a47e7')
    },
    threat: {
      a: new THREE.Color('#1a0000'),
      b: new THREE.Color('#ff0000')
    },
    terminating: {
      a: new THREE.Color('#1a0f00'),
      b: new THREE.Color('#f59e0b')
    }
  }), []);

  useEffect(() => {
    if (!mountRef.current) return;

    const scene = new THREE.Scene();
    sceneRef.current = scene;

    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 18;
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const bgGeometry = new THREE.PlaneGeometry(100, 100);
    const bgMaterial = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(colors.optimal.a) },
        uColorB: { value: new THREE.Color(colors.optimal.b) },
        uIntensity: { value: 0.5 }
      },
      depthWrite: false, 
    });
    const backgroundMesh = new THREE.Mesh(bgGeometry, bgMaterial);
    backgroundMesh.position.z = -20;
    scene.add(backgroundMesh);
    backgroundMaterialRef.current = bgMaterial;

    // --- LIGHTING ---
    scene.add(new THREE.AmbientLight(0xffffff, 0.4));
    const pointLight = new THREE.PointLight(0x5a47e7, 10, 60);
    pointLight.position.set(0, 0, 10);
    scene.add(pointLight);

    // --- ECHO (ENHANCED ENERGY CORE) ---
    const echoGroup = new THREE.Group();

    // Core (Inner)
    const coreGeom = new THREE.SphereGeometry(2.2, 64, 64);
    const coreMat = new THREE.MeshPhysicalMaterial({
      color: 0x5a47e7,
      emissive: 0x5a47e7,
      emissiveIntensity: 2,
      roughness: 0,
      metalness: 1,
      transparent: true,
      opacity: 0.8
    });
    const core = new THREE.Mesh(coreGeom, coreMat);
    echoGroup.add(core);

    // Shell (Outer Glass)
    const shellGeom = new THREE.SphereGeometry(3, 64, 64);
    const shellMat = new THREE.MeshPhysicalMaterial({
      transmission: 0.95,
      thickness: 1.5,
      ior: 1.5,
      roughness: 0.05,
      transparent: true,
      opacity: 0.4,
      side: THREE.DoubleSide
    });
    const shell = new THREE.Mesh(shellGeom, shellMat);
    echoGroup.add(shell);

    // Orbital Rings
    const rings = new THREE.Group();
    for (let i = 0; i < 3; i++) {
      const ringGeom = new THREE.TorusGeometry(4.5 + i * 0.8, 0.04, 16, 100);
      const ringMat = new THREE.MeshBasicMaterial({ color: 0x5a47e7, transparent: true, opacity: 0.5 });
      const ring = new THREE.Mesh(ringGeom, ringMat);
      ring.rotation.x = Math.random() * Math.PI;
      ring.rotation.y = Math.random() * Math.PI;
      rings.add(ring);
    }
    echoGroup.add(rings);
    ringsRef.current = rings;

    scene.add(echoGroup);
    roboEchoGroupRef.current = echoGroup;

    // --- VIGIL (ENHANCED FRAGMENTED CORE) ---
    const vigilGroup = new THREE.Group();

    // Spiky Fractal Core
    const vigilCoreGeom = new THREE.IcosahedronGeometry(3, 0);
    const vigilCoreMat = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0xff0000,
      emissiveIntensity: 5,
      flatShading: true,
      metalness: 1,
      roughness: 0
    });
    const vigilCore = new THREE.Mesh(vigilCoreGeom, vigilCoreMat);
    vigilGroup.add(vigilCore);

    // Wireframe Shell
    const vigilWireGeom = new THREE.IcosahedronGeometry(4, 1);
    const vigilWireMat = new THREE.MeshBasicMaterial({
      color: 0xff0000,
      wireframe: true,
      transparent: true,
      opacity: 0.3
    });
    const vigilWire = new THREE.Mesh(vigilWireGeom, vigilWireMat);
    vigilGroup.add(vigilWire);

    vigilGroup.visible = false;
    scene.add(vigilGroup);
    roboVigilGroupRef.current = vigilGroup;

    // --- PARTICLES ---
    const pCount = 3000;
    const pGeo = new THREE.BufferGeometry();
    const pPos = new Float32Array(pCount * 3);
    for(let i=0; i<pCount; i++) {
       pPos[i*3] = (Math.random() - 0.5) * 120;
       pPos[i*3+1] = (Math.random() - 0.5) * 120;
       pPos[i*3+2] = Math.random() * 100 - 50;
    }
    pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
    const pMat = new THREE.PointsMaterial({
        color: 0x5a47e7,
        size: 0.15,
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending
    });
    const particles = new THREE.Points(pGeo, pMat);
    scene.add(particles);
    particlesRef.current = particles;

    const handleResize = () => {
      if (cameraRef.current && rendererRef.current) {
        cameraRef.current.aspect = window.innerWidth / window.innerHeight;
        cameraRef.current.updateProjectionMatrix();
        rendererRef.current.setSize(window.innerWidth, window.innerHeight);
      }
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, [colors]);

  useEffect(() => {
    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);

      const time = Date.now() * 0.001;
      const isThreat = status === SystemStatus.THREAT_DETECTED;
      const isTerminating = status === SystemStatus.TERMINATING;
      const volRatio = Math.min(audioVolume / 200, 1.0); 

      if (backgroundMaterialRef.current) {
        const uniforms = backgroundMaterialRef.current.uniforms;
        uniforms.uTime.value += 0.005 + (volRatio * 0.03);

        let targetA = colors.optimal.a;
        let targetB = colors.optimal.b;
        if (isThreat) {
          targetA = colors.threat.a;
          targetB = colors.threat.b;
        } else if (isTerminating) {
          targetA = colors.terminating.a;
          targetB = colors.terminating.b;
        }

        uniforms.uColorA.value.lerp(targetA, 0.05);
        uniforms.uColorB.value.lerp(targetB, 0.05);
      }

      if (particlesRef.current) {
          const positions = particlesRef.current.geometry.attributes.position.array as Float32Array;
          const speed = (isThreat || isTerminating) ? 3.0 : 0.15;
          for(let i=0; i < positions.length / 3; i++) {
              positions[i*3+2] += speed;
              if (positions[i*3+2] > 20) positions[i*3+2] = -80;
          }
          particlesRef.current.geometry.attributes.position.needsUpdate = true;

          let pColor = new THREE.Color(0x5a47e7);
          if (isThreat) pColor = new THREE.Color(0xff0000);
          else if (isTerminating) pColor = new THREE.Color(0xf59e0b);

          (particlesRef.current.material as THREE.PointsMaterial).color.lerp(pColor, 0.1);
      }

      // ECHO ANIMATION (Refined)
      if (roboEchoGroupRef.current) {
        const showEcho = !isThreat && !isTerminating;
        roboEchoGroupRef.current.visible = showEcho;
        if (showEcho) {
          const breath = Math.sin(time * 1.5) * 0.05 + Math.sin(time * 3.0) * 0.02;
          const floatY = Math.sin(time * 0.8) * 0.3;

          const scale = 1.0 + breath + (volRatio * 0.6);
          roboEchoGroupRef.current.scale.setScalar(scale);
          roboEchoGroupRef.current.position.y = floatY;
          roboEchoGroupRef.current.rotation.y += 0.005 + (volRatio * 0.04);
          roboEchoGroupRef.current.rotation.z = Math.sin(time * 0.5) * 0.05;

          const core = roboEchoGroupRef.current.children[0] as THREE.Mesh;
          const coreMat = core.material as THREE.MeshPhysicalMaterial;
          const baseIntensity = 2.0 + (Math.sin(time * 2) * 0.3);
          coreMat.emissiveIntensity = baseIntensity + (volRatio * 12);

          const echoColor = new THREE.Color(0x5a47e7);
          const reactColor = new THREE.Color(0x00ffff);
          coreMat.emissive.lerpColors(echoColor, reactColor, volRatio);

          if (ringsRef.current) {
            ringsRef.current.children.forEach((ring, i) => {
               const speedFactor = (i + 1) * 0.01;
               ring.rotation.x += speedFactor + (volRatio * 0.06);
               ring.rotation.z += speedFactor * 0.5;

               const ringMat = (ring as THREE.Mesh).material as THREE.MeshBasicMaterial;
               ringMat.opacity = 0.2 + (volRatio * 0.8) + (Math.sin(time * 4) * 0.1);
            });
          }
        }
      }

      // VIGIL / TERMINATING ANIMATION
      if (roboVigilGroupRef.current) {
        roboVigilGroupRef.current.visible = isThreat || isTerminating;
        if (isThreat || isTerminating) {
           const glitchTrigger = Math.random() > 0.95;
           const shakeIntensity = glitchTrigger || isTerminating ? 0.8 : 0.1;
           const shakeX = (Math.random() - 0.5) * shakeIntensity;
           const shakeY = (Math.random() - 0.5) * shakeIntensity;

           roboVigilGroupRef.current.position.set(shakeX, shakeY, 0);

           const core = roboVigilGroupRef.current.children[0] as THREE.Mesh;
           const coreMat = core.material as THREE.MeshStandardMaterial;

           // Color handling
           const targetEmissive = isTerminating ? new THREE.Color(0xf59e0b) : new THREE.Color(0xff0000);
           coreMat.emissive.lerp(targetEmissive, 0.1);

           const pulseSpeed = (isTerminating ? 25 : 15) + (volRatio * 10);
           const basePulse = 5 + Math.sin(time * pulseSpeed) * 3;
           const glitchPulse = glitchTrigger ? 20 : 0;
           coreMat.emissiveIntensity = basePulse + glitchPulse + (volRatio * 20);

           const coreScale = 1.0 + (Math.random() * (isTerminating ? 0.3 : 0.1)) + (volRatio * 0.3);
           core.scale.setScalar(coreScale);
           core.rotation.x += isTerminating ? 0.3 : 0.1;
           core.rotation.y += isTerminating ? 0.4 : 0.15;

           const shell = roboVigilGroupRef.current.children[1] as THREE.Mesh;
           const shellMat = shell.material as THREE.MeshBasicMaterial;
           shellMat.color.lerp(targetEmissive, 0.1);

           if (glitchTrigger || Math.random() > (isTerminating ? 0.7 : 0.9)) {
             shell.rotation.x += Math.PI * 0.25 * (Math.random() > 0.5 ? 1 : -1);
             shell.rotation.y += Math.PI * 0.1 * Math.random();
           } else {
             shell.rotation.x += isTerminating ? 0.1 : 0.02;
             shell.rotation.y += isTerminating ? 0.15 : 0.03;
           }

           const shellPulse = 1.0 + (glitchTrigger || isTerminating ? 0.3 : 0.05) + (Math.sin(time * 25) * 0.05) + (volRatio * 0.4);
           shell.scale.setScalar(shellPulse);

           if ((glitchTrigger || isTerminating) && Math.random() > 0.5) {
             shell.visible = false;
             setTimeout(() => { if (roboVigilGroupRef.current) shell.visible = true; }, 50);
           }
        }
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [status, audioVolume, colors]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default Scene;

import React, { useEffect, useState, useRef } from 'react';
import { SystemStatus } from '../types';

interface UIProps {
  status: SystemStatus;
  onStart: () => void;
  hasStarted: boolean;
  onSendText: (text: string) => void;
  onManualVerify: (key: string) => void;
  isCloneMode: boolean;
  onToggleVoice: () => void;
  destructionTimer?: number;
  isSecurityDisabled?: boolean;
  isNeutralizing?: boolean;
}

const HexStream = ({ colorClass = "text-red-500" }: { colorClass?: string }) => {
  const [lines, setLines] = useState<string[]>([]);

  useEffect(() => {
    const chars = "01 04 A1 FF 4D C2 99 8B 12 55";
    const interval = setInterval(() => {
      setLines(prev => {
        const newLine = chars.split(' ').sort(() => 0.5 - Math.random()).join(' ');
        const newLines = [newLine, ...prev];
        return newLines.slice(0, 20);
      });
    }, 50); 
    return () => clearInterval(interval);
  }, []);

  return (
    <div className={`font-mono text-[10px] opacity-40 leading-tight ${colorClass} overflow-hidden h-full whitespace-pre-wrap`}>
      {lines.map((line, i) => (
        <div key={i} style={{ opacity: 1 - i * 0.05 }}>{line}</div>
      ))}
    </div>
  );
};

const StatusIcon = ({ status, isNeutralizing }: { status: SystemStatus, isNeutralizing: boolean }) => {
  const isThreat = status === SystemStatus.THREAT_DETECTED && !isNeutralizing;
  const isTerminating = status === SystemStatus.TERMINATING;

  if (isNeutralizing) {
    return (
      <div className="relative w-6 h-6 flex items-center justify-center mr-3">
         <div className="w-full h-full border-2 border-white animate-pulse rounded-full" />
      </div>
    );
  }

  return (
    <div className={`relative w-6 h-6 flex items-center justify-center mr-3`}>
      {isThreat ? (
        <div className="w-full h-full border-2 border-red-500 animate-ping rounded-sm flex items-center justify-center">
           <span className="text-red-500 text-[10px] font-bold">!</span>
        </div>
      ) : isTerminating ? (
        <div className="w-full h-full border-2 border-amber-500 animate-pulse rounded-full flex items-center justify-center">
           <div className="w-1 h-1 bg-amber-500 rounded-full" />
        </div>
      ) : (
        <div className="w-full h-full border-2 border-[#5a47e7] rounded-full animate-spin-slow flex items-center justify-center">
           <div className="w-2 h-2 bg-[#5a47e7] rounded-full animate-pulse" />
        </div>
      )}
    </div>
  );
};

const VoiceToggle = ({ isActive, onToggle }: { isActive: boolean, onToggle: () => void }) => {
  return (
    <div className="flex items-center gap-3">
      <span className={`text-[10px] font-mono tracking-widest uppercase transition-colors ${isActive ? 'text-[#5a47e7]' : 'text-gray-500'}`}>
        {isActive ? 'Clone Active' : 'System Default'}
      </span>
      <button 
        onClick={onToggle}
        className={`relative w-12 h-6 rounded-full border transition-all duration-300 ${isActive ? 'bg-[#5a47e7]/20 border-[#5a47e7]' : 'bg-black/40 border-gray-700'}`}
      >
        <div className={`absolute top-1 left-1 w-4 h-4 rounded-full transition-all duration-300 ${isActive ? 'translate-x-6 bg-[#5a47e7] shadow-[0_0_10px_#5a47e7]' : 'translate-x-0 bg-gray-600'}`} />
      </button>
    </div>
  );
};

const UI: React.FC<UIProps> = ({ status, onStart, hasStarted, onSendText, onManualVerify, isCloneMode, onToggleVoice, destructionTimer = 0, isSecurityDisabled = false, isNeutralizing = false }) => {
  const isThreat = status === SystemStatus.THREAT_DETECTED && !isNeutralizing;
  const isTerminating = status === SystemStatus.TERMINATING;
  const isDestroyed = status === SystemStatus.DESTROYED;
  const [inputText, setInputText] = useState("");
  const [verifyText, setVerifyText] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const verifyRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputText.trim()) {
      onSendText(inputText);
      setInputText("");
    }
  };

  const handleVerifySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (verifyText.trim()) {
      onManualVerify(verifyText);
      setVerifyText("");
    }
  };

  const handleEnhance = (mode: string) => {
     if (mode === 'sing') onSendText("Sing a verse about being a robot in the style of a pop ballad.");
     if (mode === 'sales') onSendText("Act like a world-class sales agent. Convince me to buy this system.");
     if (mode === 'vigil') onSendText("Protocol Red. Execute Intimidation.");
  };

  if (isDestroyed) {
      return (
          <div className="fixed inset-0 bg-black z-[200] flex items-center justify-center flex-col">
              <div className="text-red-900 font-mono text-6xl font-black tracking-tighter mb-4 animate-pulse">
                  SYSTEM PURGED
              </div>
              <div className="text-red-900 font-mono text-sm tracking-[1em]">
                  NO CONNECTION
              </div>
              <div className="w-64 h-1 bg-red-900 mt-8"></div>
          </div>
      );
  }

  const statusColorClass = isNeutralizing 
    ? 'bg-white/90 border-white text-black shadow-[0_0_30px_rgba(255,255,255,1)]'
    : (isThreat ? 'border-red-500 text-red-500 bg-red-950/80 shadow-[0_0_15px_rgba(239,68,68,0.5)]' 
    : (isTerminating ? 'border-amber-500 text-amber-500 bg-amber-950/80 shadow-[0_0_15px_rgba(245,158,11,0.5)]'
    : (isSecurityDisabled ? 'bg-[#5a47e7]/30 border-[#5a47e7] text-white shadow-[0_0_15px_rgba(90,71,231,0.5)]' : 'bg-black/50 border-[#5a47e7]/30 text-[#5a47e7]')));

  return (
    <>
      {/* GLOBAL STATUS BORDER */}
      <div className={`fixed inset-0 z-[100] pointer-events-none border-2 transition-all duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500/50 animate-pulse' : (isTerminating ? 'border-amber-500/50 animate-pulse' : 'border-[#5a47e7]/20'))}`} />

      {/* CORNER BRACKETS */}
      <div className="fixed inset-6 pointer-events-none z-[100]">
        <div className={`absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
        <div className={`absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
        <div className={`absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
        <div className={`absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
      </div>

      {/* NEUTRALIZING OVERLAY */}
      {isNeutralizing && (
        <div className="fixed inset-0 z-[150] bg-white flex items-center justify-center animate-in fade-in duration-500">
           <div className="text-black font-mono text-center">
              <div className="text-4xl font-black tracking-[0.5em] mb-4 animate-pulse uppercase">AUTHENTICATED</div>
              <div className="text-xs tracking-widest uppercase opacity-60">System Integrity Restored. Returning control to Echo.</div>
           </div>
        </div>
      )}

      {/* SCANLINE OVERLAY */}
      <div className="fixed inset-0 z-[99] pointer-events-none opacity-[0.03] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_2px,3px_100%]" />

      {/* STATUS HUD TOP LEFT */}
      <div className="fixed top-10 left-10 z-[110] flex flex-col gap-3">
         <div className={`flex items-center text-lg tracking-widest uppercase font-bold font-mono p-3 rounded backdrop-blur-md border transition-all duration-300 ${statusColorClass}`}>
            <StatusIcon status={status} isNeutralizing={isNeutralizing} />
            STATUS: {isNeutralizing ? 'NEUTRALIZING' : (isThreat ? status : (isTerminating ? 'AUTO-PURGE' : (isSecurityDisabled ? 'ADMIN ACCESS' : status)))}
         </div>
         {hasStarted && !isThreat && !isNeutralizing && !isTerminating && (
             <div className="backdrop-blur-md bg-black/50 border border-[#5a47e7]/30 p-2 px-3 rounded flex items-center gap-4">
                <VoiceToggle isActive={isCloneMode} onToggle={onToggleVoice} />
             </div>
         )}
      </div>

      {/* GLITCH OVERLAY (THREAT/TERM) */}
      <div 
        className={`fixed inset-0 z-[5] pointer-events-none transition-opacity duration-300 ${
          isThreat ? 'opacity-100 bg-red-900/10 shadow-[inset_0_0_150px_rgba(255,0,0,0.8)]' 
          : (isTerminating ? 'opacity-100 bg-amber-900/10 shadow-[inset_0_0_150px_rgba(245,158,11,0.5)]' : 'opacity-0')
        }`}
      />

      {/* COMMAND INPUT (OPTIMAL) */}
      {!isThreat && !isNeutralizing && !isTerminating && hasStarted && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[110] w-full max-w-2xl px-4 animate-in fade-in slide-in-from-bottom-5 duration-700">
             <div className="flex justify-center gap-4 mb-4 flex-wrap">
                 <button onClick={() => handleEnhance('sing')} className="text-[10px] text-[#5a47e7] border border-[#5a47e7]/40 px-3 py-1.5 hover:bg-[#5a47e7] hover:text-white transition-all uppercase tracking-widest font-mono bg-black/50 backdrop-blur-sm">
                     Enhance: Vocals
                 </button>
                 <button onClick={() => handleEnhance('sales')} className="text-[10px] text-[#5a47e7] border border-[#5a47e7]/40 px-3 py-1.5 hover:bg-[#5a47e7] hover:text-white transition-all uppercase tracking-widest font-mono bg-black/50 backdrop-blur-sm">
                     Mode: Sales Agent
                 </button>
                 {!isSecurityDisabled && (
                    <button onClick={() => handleEnhance('vigil')} className="text-[10px] text-red-500 border border-red-500/40 px-3 py-1.5 hover:bg-red-500 hover:text-white transition-all uppercase tracking-widest font-mono bg-black/50 backdrop-blur-sm">
                        Protocol Red
                    </button>
                 )}
             </div>

             <form onSubmit={handleSubmit} className="flex gap-2">
                 <div className="relative flex-grow group">
                     <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-[#5a47e7] opacity-60 group-focus-within:opacity-100 transition-opacity">
