import React, { useEffect, useRef, useMemo } from 'react';
import * as THREE from 'three';
import { SystemStatus } from '../types';

interface SceneProps {
  status: SystemStatus;
  audioVolume: number;
}

// --- GLSL SHADERS ---

const vertexShader = `
  varying vec2 vUv;
  varying vec3 vPosition;
  varying vec3 vNormal;
  void main() {
    vUv = uv;
    vPosition = position;
    vNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uIntensity;
  varying vec2 vUv;

  void main() {
    vec2 uv = vUv;

    for(float i = 1.0; i < 4.0; i++){
        uv.x += 0.6 / i * cos(i * 2.5 * uv.y + uTime * 0.5);
        uv.y += 0.6 / i * cos(i * 1.5 * uv.x + uTime * 0.5);
    }

    float strength = 0.5 + 0.5 * sin(uv.x * 10.0 + uTime);
    vec3 color = mix(uColorA, uColorB, strength * uIntensity);

    float dist = distance(vUv, vec2(0.5));
    color *= 1.0 - dist * 0.8;

    gl_FragColor = vec4(color, 1.0);
  }
`;

const Scene: React.FC<SceneProps> = ({ status, audioVolume }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const backgroundMaterialRef = useRef<THREE.ShaderMaterial | null>(null);

  const roboEchoGroupRef = useRef<THREE.Group | null>(null);
  const roboVigilGroupRef = useRef<THREE.Group | null>(null);
  const ringsRef = useRef<THREE.Group | null>(null);

  const particlesRef = useRef<THREE.Points | null>(null);
  const animationFrameRef = useRef<number>(0);

  const colors = useMemo(() => ({
    optimal: {
      a: new THREE.Color('#0c0018'),
      b: new THREE.Color('#5a47e7')
    },
    threat: {
      a: new THREE.Color('#1a0000'),
      b: new THREE.Color('#ff0000')
    },
    terminating: {
      a: new THREE.Color('#1a0f00'),
      b: new THREE.Color('#f59e0b')
    }
  }), []);

  useEffect(() => {
    if (!mountRef.current) return;

    const scene = new THREE.Scene();
    sceneRef.current = scene;

    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 18;
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const bgGeometry = new THREE.PlaneGeometry(100, 100);
    const bgMaterial = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(colors.optimal.a) },
        uColorB: { value: new THREE.Color(colors.optimal.b) },
        uIntensity: { value: 0.5 }
      },
      depthWrite: false, 
    });
    const backgroundMesh = new THREE.Mesh(bgGeometry, bgMaterial);
    backgroundMesh.position.z = -20;
    scene.add(backgroundMesh);
    backgroundMaterialRef.current = bgMaterial;

    // --- LIGHTING ---
    scene.add(new THREE.AmbientLight(0xffffff, 0.4));
    const pointLight = new THREE.PointLight(0x5a47e7, 10, 60);
    pointLight.position.set(0, 0, 10);
    scene.add(pointLight);

    // --- ECHO (ENHANCED ENERGY CORE) ---
    const echoGroup = new THREE.Group();

    // Core (Inner)
    const coreGeom = new THREE.SphereGeometry(2.2, 64, 64);
    const coreMat = new THREE.MeshPhysicalMaterial({
      color: 0x5a47e7,
      emissive: 0x5a47e7,
      emissiveIntensity: 2,
      roughness: 0,
      metalness: 1,
      transparent: true,
      opacity: 0.8
    });
    const core = new THREE.Mesh(coreGeom, coreMat);
    echoGroup.add(core);

    // Shell (Outer Glass)
    const shellGeom = new THREE.SphereGeometry(3, 64, 64);
    const shellMat = new THREE.MeshPhysicalMaterial({
      transmission: 0.95,
      thickness: 1.5,
      ior: 1.5,
      roughness: 0.05,
      transparent: true,
      opacity: 0.4,
      side: THREE.DoubleSide
    });
    const shell = new THREE.Mesh(shellGeom, shellMat);
    echoGroup.add(shell);

    // Orbital Rings
    const rings = new THREE.Group();
    for (let i = 0; i < 3; i++) {
      const ringGeom = new THREE.TorusGeometry(4.5 + i * 0.8, 0.04, 16, 100);
      const ringMat = new THREE.MeshBasicMaterial({ color: 0x5a47e7, transparent: true, opacity: 0.5 });
      const ring = new THREE.Mesh(ringGeom, ringMat);
      ring.rotation.x = Math.random() * Math.PI;
      ring.rotation.y = Math.random() * Math.PI;
      rings.add(ring);
    }
    echoGroup.add(rings);
    ringsRef.current = rings;

    scene.add(echoGroup);
    roboEchoGroupRef.current = echoGroup;

    // --- VIGIL (ENHANCED FRAGMENTED CORE) ---
    const vigilGroup = new THREE.Group();

    // Spiky Fractal Core
    const vigilCoreGeom = new THREE.IcosahedronGeometry(3, 0);
    const vigilCoreMat = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0xff0000,
      emissiveIntensity: 5,
      flatShading: true,
      metalness: 1,
      roughness: 0
    });
    const vigilCore = new THREE.Mesh(vigilCoreGeom, vigilCoreMat);
    vigilGroup.add(vigilCore);

    // Wireframe Shell
    const vigilWireGeom = new THREE.IcosahedronGeometry(4, 1);
    const vigilWireMat = new THREE.MeshBasicMaterial({
      color: 0xff0000,
      wireframe: true,
      transparent: true,
      opacity: 0.3
    });
    const vigilWire = new THREE.Mesh(vigilWireGeom, vigilWireMat);
    vigilGroup.add(vigilWire);

    vigilGroup.visible = false;
    scene.add(vigilGroup);
    roboVigilGroupRef.current = vigilGroup;

    // --- PARTICLES ---
    const pCount = 3000;
    const pGeo = new THREE.BufferGeometry();
    const pPos = new Float32Array(pCount * 3);
    for(let i=0; i<pCount; i++) {
       pPos[i*3] = (Math.random() - 0.5) * 120;
       pPos[i*3+1] = (Math.random() - 0.5) * 120;
       pPos[i*3+2] = Math.random() * 100 - 50;
    }
    pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
    const pMat = new THREE.PointsMaterial({
        color: 0x5a47e7,
        size: 0.15,
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending
    });
    const particles = new THREE.Points(pGeo, pMat);
    scene.add(particles);
    particlesRef.current = particles;

    const handleResize = () => {
      if (cameraRef.current && rendererRef.current) {
        cameraRef.current.aspect = window.innerWidth / window.innerHeight;
        cameraRef.current.updateProjectionMatrix();
        rendererRef.current.setSize(window.innerWidth, window.innerHeight);
      }
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, [colors]);

  useEffect(() => {
    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);

      const time = Date.now() * 0.001;
      const isThreat = status === SystemStatus.THREAT_DETECTED;
      const isTerminating = status === SystemStatus.TERMINATING;
      const volRatio = Math.min(audioVolume / 200, 1.0); 

      if (backgroundMaterialRef.current) {
        const uniforms = backgroundMaterialRef.current.uniforms;
        uniforms.uTime.value += 0.005 + (volRatio * 0.03);

        let targetA = colors.optimal.a;
        let targetB = colors.optimal.b;
        if (isThreat) {
          targetA = colors.threat.a;
          targetB = colors.threat.b;
        } else if (isTerminating) {
          targetA = colors.terminating.a;
          targetB = colors.terminating.b;
        }

        uniforms.uColorA.value.lerp(targetA, 0.05);
        uniforms.uColorB.value.lerp(targetB, 0.05);
      }

      if (particlesRef.current) {
          const positions = particlesRef.current.geometry.attributes.position.array as Float32Array;
          const speed = (isThreat || isTerminating) ? 3.0 : 0.15;
          for(let i=0; i < positions.length / 3; i++) {
              positions[i*3+2] += speed;
              if (positions[i*3+2] > 20) positions[i*3+2] = -80;
          }
          particlesRef.current.geometry.attributes.position.needsUpdate = true;

          let pColor = new THREE.Color(0x5a47e7);
          if (isThreat) pColor = new THREE.Color(0xff0000);
          else if (isTerminating) pColor = new THREE.Color(0xf59e0b);

          (particlesRef.current.material as THREE.PointsMaterial).color.lerp(pColor, 0.1);
      }

      // ECHO ANIMATION (Refined)
      if (roboEchoGroupRef.current) {
        const showEcho = !isThreat && !isTerminating;
        roboEchoGroupRef.current.visible = showEcho;
        if (showEcho) {
          const breath = Math.sin(time * 1.5) * 0.05 + Math.sin(time * 3.0) * 0.02;
          const floatY = Math.sin(time * 0.8) * 0.3;

          const scale = 1.0 + breath + (volRatio * 0.6);
          roboEchoGroupRef.current.scale.setScalar(scale);
          roboEchoGroupRef.current.position.y = floatY;
          roboEchoGroupRef.current.rotation.y += 0.005 + (volRatio * 0.04);
          roboEchoGroupRef.current.rotation.z = Math.sin(time * 0.5) * 0.05;

          const core = roboEchoGroupRef.current.children[0] as THREE.Mesh;
          const coreMat = core.material as THREE.MeshPhysicalMaterial;
          const baseIntensity = 2.0 + (Math.sin(time * 2) * 0.3);
          coreMat.emissiveIntensity = baseIntensity + (volRatio * 12);

          const echoColor = new THREE.Color(0x5a47e7);
          const reactColor = new THREE.Color(0x00ffff);
          coreMat.emissive.lerpColors(echoColor, reactColor, volRatio);

          if (ringsRef.current) {
            ringsRef.current.children.forEach((ring, i) => {
               const speedFactor = (i + 1) * 0.01;
               ring.rotation.x += speedFactor + (volRatio * 0.06);
               ring.rotation.z += speedFactor * 0.5;

               const ringMat = (ring as THREE.Mesh).material as THREE.MeshBasicMaterial;
               ringMat.opacity = 0.2 + (volRatio * 0.8) + (Math.sin(time * 4) * 0.1);
            });
          }
        }
      }

      // VIGIL / TERMINATING ANIMATION (Refined Glitch)
      if (roboVigilGroupRef.current) {
        roboVigilGroupRef.current.visible = isThreat || isTerminating;
        if (isThreat || isTerminating) {
           // Percussive glitch frequency depends on state and volume
           const glitchThreshold = isTerminating ? 0.85 : 0.94;
           const isGlitching = Math.random() > glitchThreshold;

           // Shake effect for the entire group
           const shakeIntensity = (isTerminating ? 1.2 : 0.4) * (isGlitching ? 1.5 : 1.0);
           const shakeX = (Math.random() - 0.5) * shakeIntensity;
           const shakeY = (Math.random() - 0.5) * shakeIntensity;
           roboVigilGroupRef.current.position.set(shakeX, shakeY, 0);

           const core = roboVigilGroupRef.current.children[0] as THREE.Mesh;
           const coreMat = core.material as THREE.MeshStandardMaterial;

           // Color handling
           const targetEmissive = isTerminating ? new THREE.Color(0xf59e0b) : new THREE.Color(0xff0000);
           coreMat.emissive.lerp(targetEmissive, 0.1);

           // Aggressive pulsing emissive with random spikes
           const pulseSpeed = (isTerminating ? 40 : 20) + (volRatio * 30);
           const basePulse = 5 + Math.sin(time * pulseSpeed) * 4;
           const spike = isGlitching ? 30 : 0;
           coreMat.emissiveIntensity = basePulse + spike + (volRatio * 25);

           // Jitter core scale aggressively
           const jitterScale = 1.0 + (isGlitching ? (Math.random() * 0.4) : (Math.random() * 0.1));
           const coreScale = jitterScale + (volRatio * 0.5);
           core.scale.setScalar(coreScale);

           // Rotations become more percussive (stepped)
           const rotStep = isTerminating ? Math.PI * 0.1 : 0.05;
           if (isGlitching) {
              core.rotation.x += (Math.random() - 0.5) * 2.0;
              core.rotation.y += (Math.random() - 0.5) * 2.0;
           } else {
              core.rotation.x += rotStep + (volRatio * 0.2);
              core.rotation.y += rotStep * 1.5;
           }

           const shell = roboVigilGroupRef.current.children[1] as THREE.Mesh;
           const shellMat = shell.material as THREE.MeshBasicMaterial;
           shellMat.color.lerp(targetEmissive, 0.1);

           // Percussive "fragmented" rotations for shell
           if (isGlitching || Math.random() > 0.9) {
             // Snap to discrete angles for digital look
             const angles = [0, Math.PI * 0.5, Math.PI, Math.PI * 1.5];
             shell.rotation.x = angles[Math.floor(Math.random() * angles.length)];
             shell.rotation.y = angles[Math.floor(Math.random() * angles.length)];

             // Rapid translation offset for fragmented feel
             const fragOffset = (Math.random() - 0.5) * (isTerminating ? 2.0 : 0.8);
             shell.position.set(fragOffset, -fragOffset, fragOffset * 0.5);
           } else {
             shell.rotation.x += isTerminating ? 0.12 : 0.03;
             shell.rotation.y += isTerminating ? 0.18 : 0.05;
             shell.position.lerp(new THREE.Vector3(0, 0, 0), 0.2);
           }

           const shellPulse = 1.0 + (isGlitching ? 0.4 : 0.05) + (Math.sin(time * 35) * 0.05) + (volRatio * 0.6);
           shell.scale.setScalar(shellPulse);

           // High-speed flicker
           if ((isGlitching || isTerminating) && Math.random() > (isTerminating ? 0.3 : 0.6)) {
             shell.visible = false;
             // Use a small delay for visible flickering
             setTimeout(() => { if (roboVigilGroupRef.current) shell.visible = true; }, 30);
           }
        }
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [status, audioVolume, colors]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

