import React, { useEffect, useRef, useMemo } from 'react';
import * as THREE from 'three';
import { SystemStatus } from '../types';

interface SceneProps {
  status: SystemStatus;
  audioVolume: number;
}

const vertexShader = `
  varying vec2 vUv;
  varying vec3 vPosition;
  varying vec3 vNormal;
  void main() {
    vUv = uv;
    vPosition = position;
    vNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uIntensity;
  varying vec2 vUv;

  void main() {
    vec2 uv = vUv;
    float t = uTime * 0.2;

    for(float i = 1.0; i < 5.0; i++){
        uv.x += 0.3 / i * cos(i * 3.0 * uv.y + t);
        uv.y += 0.3 / i * cos(i * 2.0 * uv.x + t);
    }

    float strength = 0.5 + 0.5 * sin(uv.x * 12.0 + uTime);
    vec3 color = mix(uColorA, uColorB, strength * uIntensity);

    // Vignette
    float dist = distance(vUv, vec2(0.5));
    color *= 1.2 - dist * 1.1;

    // Scanlines
    float scanline = sin(vUv.y * 800.0) * 0.04;
    color -= scanline;

    gl_FragColor = vec4(color, 1.0);
  }
`;

const Scene: React.FC<SceneProps> = ({ status, audioVolume }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const backgroundMaterialRef = useRef<THREE.ShaderMaterial | null>(null);

  const roboEchoGroupRef = useRef<THREE.Group | null>(null);
  const roboVigilGroupRef = useRef<THREE.Group | null>(null);
  const ringsRef = useRef<THREE.Group | null>(null);
  const lightningRef = useRef<THREE.Group | null>(null);
  const debrisRef = useRef<THREE.Points | null>(null);

  const particlesRef = useRef<THREE.Points | null>(null);
  const animationFrameRef = useRef<number>(0);

  const colors = useMemo(() => ({
    optimal: {
      a: new THREE.Color('#05000a'),
      b: new THREE.Color('#4e36e0')
    },
    threat: {
      a: new THREE.Color('#0f0000'),
      b: new THREE.Color('#cc0000')
    },
    terminating: {
      a: new THREE.Color('#140b00'),
      b: new THREE.Color('#e08e00')
    }
  }), []);

  useEffect(() => {
    if (!mountRef.current) return;

    const scene = new THREE.Scene();
    sceneRef.current = scene;

    const camera = new THREE.PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 20;
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, stencil: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x000000);
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Background
    const bgGeometry = new THREE.PlaneGeometry(120, 120);
    const bgMaterial = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(colors.optimal.a) },
        uColorB: { value: new THREE.Color(colors.optimal.b) },
        uIntensity: { value: 0.6 }
      },
      depthWrite: false, 
    });
    const backgroundMesh = new THREE.Mesh(bgGeometry, bgMaterial);
    backgroundMesh.position.z = -25;
    scene.add(backgroundMesh);
    backgroundMaterialRef.current = bgMaterial;

    // Lighting
    scene.add(new THREE.AmbientLight(0xffffff, 0.2));
    const mainLight = new THREE.PointLight(0xffffff, 5, 100);
    mainLight.position.set(10, 10, 10);
    scene.add(mainLight);

    const rimLight = new THREE.SpotLight(0x5a47e7, 15);
    rimLight.position.set(-20, 20, 10);
    scene.add(rimLight);

    // --- ECHO (ENHANCED) ---
    const echoGroup = new THREE.Group();

    // Core (Heart)
    const coreGeom = new THREE.SphereGeometry(2.4, 64, 64);
    const coreMat = new THREE.MeshPhysicalMaterial({
      color: 0x5a47e7,
      emissive: 0x5a47e7,
      emissiveIntensity: 3,
      roughness: 0.1,
      metalness: 0.9,
      transparent: true,
      opacity: 0.9,
      ior: 2.5,
      thickness: 1.0,
      transmission: 0.5
    });
    const core = new THREE.Mesh(coreGeom, coreMat);
    echoGroup.add(core);

    // Floating Particles inside shell
    const innerPCount = 200;
    const innerPGeo = new THREE.BufferGeometry();
    const innerPPos = new Float32Array(innerPCount * 3);
    for(let i=0; i<innerPCount; i++){
        const r = 2.6 + Math.random() * 0.4;
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.random() * Math.PI;
        innerPPos[i*3] = r * Math.sin(phi) * Math.cos(theta);
        innerPPos[i*3+1] = r * Math.sin(phi) * Math.sin(theta);
        innerPPos[i*3+2] = r * Math.cos(phi);
    }
    innerPGeo.setAttribute('position', new THREE.BufferAttribute(innerPPos, 3));
    const innerPMaterial = new THREE.PointsMaterial({ color: 0x00ffff, size: 0.05, transparent: true, opacity: 0.8 });
    const innerParticles = new THREE.Points(innerPGeo, innerPMaterial);
    echoGroup.add(innerParticles);

    // Outer Shell
    const shellGeom = new THREE.SphereGeometry(3.5, 64, 64);
    const shellMat = new THREE.MeshPhysicalMaterial({
      color: 0xffffff,
      transmission: 0.98,
      thickness: 2.0,
      ior: 1.45,
      roughness: 0.0,
      metalness: 0.1,
      transparent: true,
      opacity: 0.2,
      side: THREE.DoubleSide,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1
    });
    const shell = new THREE.Mesh(shellGeom, shellMat);
    echoGroup.add(shell);

    // Orbital Warp Rings
    const rings = new THREE.Group();
    for (let i = 0; i < 4; i++) {
      const ringGeom = new THREE.TorusGeometry(5.0 + i * 1.2, 0.02, 16, 100);
      const ringMat = new THREE.MeshBasicMaterial({ color: 0x5a47e7, transparent: true, opacity: 0.3 });
      const ring = new THREE.Mesh(ringGeom, ringMat);
      ring.rotation.x = Math.random() * Math.PI;
      ring.rotation.y = Math.random() * Math.PI;
      rings.add(ring);
    }
    echoGroup.add(rings);
    ringsRef.current = rings;

    scene.add(echoGroup);
    roboEchoGroupRef.current = echoGroup;

    // --- VIGIL (FRAGMENTED) ---
    const vigilGroup = new THREE.Group();

    // Core (Fragmented)
    const vigilCoreGeom = new THREE.IcosahedronGeometry(3.2, 0);
    const vigilCoreMat = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0xff0000,
      emissiveIntensity: 10,
      flatShading: true,
      metalness: 1,
      roughness: 0.2
    });
    const vigilCore = new THREE.Mesh(vigilCoreGeom, vigilCoreMat);
    vigilGroup.add(vigilCore);

    // Wireframe Glitch Shell
    const vigilWireGeom = new THREE.IcosahedronGeometry(4.5, 2);
    const vigilWireMat = new THREE.MeshBasicMaterial({
      color: 0xff0000,
      wireframe: true,
      transparent: true,
      opacity: 0.4
    });
    const vigilWire = new THREE.Mesh(vigilWireGeom, vigilWireMat);
    vigilGroup.add(vigilWire);

    // Lightning streaks
    const lGroup = new THREE.Group();
    for(let i=0; i<5; i++){
        const lPoints = [];
        for(let j=0; j<5; j++) lPoints.push(new THREE.Vector3((Math.random()-0.5)*10, (Math.random()-0.5)*10, (Math.random()-0.5)*10));
        const lGeo = new THREE.BufferGeometry().setFromPoints(lPoints);
        const lMat = new THREE.LineBasicMaterial({ color: 0xff0000, transparent: true, opacity: 0 });
        const line = new THREE.Line(lGeo, lMat);
        lGroup.add(line);
    }
    vigilGroup.add(lGroup);
    lightningRef.current = lGroup;

    vigilGroup.visible = false;
    scene.add(vigilGroup);
    roboVigilGroupRef.current = vigilGroup;

    // Debris particles (sparks for termination)
    const debrisCount = 1000;
    const debrisGeo = new THREE.BufferGeometry();
    const debrisPos = new Float32Array(debrisCount * 3);
    const debrisVel = new Float32Array(debrisCount * 3);
    for(let i=0; i<debrisCount; i++) {
        debrisPos[i*3] = 0; debrisPos[i*3+1] = 0; debrisPos[i*3+2] = 0;
        debrisVel[i*3] = (Math.random() - 0.5) * 1.5;
        debrisVel[i*3+1] = (Math.random() - 0.5) * 1.5;
        debrisVel[i*3+2] = (Math.random() - 0.5) * 1.5;
    }
    debrisGeo.setAttribute('position', new THREE.BufferAttribute(debrisPos, 3));
    debrisGeo.setAttribute('velocity', new THREE.BufferAttribute(debrisVel, 3));
    const debrisMat = new THREE.PointsMaterial({ color: 0xff9900, size: 0.1, transparent: true, opacity: 0 });
    const debris = new THREE.Points(debrisGeo, debrisMat);
    scene.add(debris);
    debrisRef.current = debris;

    // World Particles
    const pCount = 4000;
    const pGeo = new THREE.BufferGeometry();
    const pPos = new Float32Array(pCount * 3);
    for(let i=0; i<pCount; i++) {
       pPos[i*3] = (Math.random() - 0.5) * 150;
       pPos[i*3+1] = (Math.random() - 0.5) * 150;
       pPos[i*3+2] = Math.random() * 100 - 50;
    }
    pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
    const pMat = new THREE.PointsMaterial({
        color: 0x5a47e7,
        size: 0.12,
        transparent: true,
        opacity: 0.5,
        blending: THREE.AdditiveBlending
    });
    const particles = new THREE.Points(pGeo, pMat);
    scene.add(particles);
    particlesRef.current = particles;

    const handleResize = () => {
      if (cameraRef.current && rendererRef.current) {
        cameraRef.current.aspect = window.innerWidth / window.innerHeight;
        cameraRef.current.updateProjectionMatrix();
        rendererRef.current.setSize(window.innerWidth, window.innerHeight);
      }
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, [colors]);

  useEffect(() => {
    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);

      const time = Date.now() * 0.001;
      const isThreat = status === SystemStatus.THREAT_DETECTED;
      const isTerminating = status === SystemStatus.TERMINATING;
      const isExtreme = isThreat || isTerminating;
      const volRatio = Math.min(audioVolume / 180, 1.0); 

      if (backgroundMaterialRef.current) {
        const uniforms = backgroundMaterialRef.current.uniforms;
        uniforms.uTime.value += 0.004 + (volRatio * 0.04);

        let targetA = colors.optimal.a;
        let targetB = colors.optimal.b;
        if (isThreat) {
          targetA = colors.threat.a;
          targetB = colors.threat.b;
        } else if (isTerminating) {
          targetA = colors.terminating.a;
          targetB = colors.terminating.b;
        }

        uniforms.uColorA.value.lerp(targetA, 0.04);
        uniforms.uColorB.value.lerp(targetB, 0.04);
        uniforms.uIntensity.value = THREE.MathUtils.lerp(uniforms.uIntensity.value, isExtreme ? 0.9 : 0.6, 0.05);
      }

      // Camera Breathing & Shake
      if (cameraRef.current) {
        cameraRef.current.position.y = Math.sin(time * 0.6) * 0.5;
        cameraRef.current.position.x = Math.cos(time * 0.4) * 0.3;

        if (isExtreme) {
            const shakeAmt = isTerminating ? 0.6 : 0.1;
            const shake = (Math.random() - 0.5) * shakeAmt * (Math.random() > 0.9 ? 3.0 : 1.0);
            cameraRef.current.position.x += shake;
            cameraRef.current.position.y += shake;
        }
      }

      if (particlesRef.current) {
          const positions = particlesRef.current.geometry.attributes.position.array as Float32Array;
          const speed = isExtreme ? 4.0 : 0.1;
          for(let i=0; i < positions.length / 3; i++) {
              positions[i*3+2] += speed;
              if (positions[i*3+2] > 20) positions[i*3+2] = -80;
          }
          particlesRef.current.geometry.attributes.position.needsUpdate = true;

          let pColor = new THREE.Color(0x5a47e7);
          if (isThreat) pColor = new THREE.Color(0xff0000);
          else if (isTerminating) pColor = new THREE.Color(0xff9900);

          (particlesRef.current.material as THREE.PointsMaterial).color.lerp(pColor, 0.05);
      }

      // ECHO ANIMATION
      if (roboEchoGroupRef.current) {
        // User requested signs of damage during Terminating state
        const showEcho = !isThreat; // Keep Echo visible in Terminating but broken
        roboEchoGroupRef.current.visible = showEcho;

        if (showEcho) {
          const isBroken = isTerminating;
          const glitchFlicker = isBroken && Math.random() > 0.8;

          const breath = Math.sin(time * 1.8) * 0.08;
          const baseScale = 1.0 + breath + (volRatio * 0.5);
          roboEchoGroupRef.current.scale.setScalar(isBroken ? baseScale * (0.8 + Math.random()*0.1) : baseScale);

          // Erratic rotation if broken
          if (isBroken) {
              roboEchoGroupRef.current.rotation.y += 0.02 * (Math.random() > 0.9 ? 5 : 1);
              roboEchoGroupRef.current.rotation.x += (Math.random() - 0.5) * 0.05;
          } else {
              roboEchoGroupRef.current.rotation.y += 0.003 + (volRatio * 0.05);
              roboEchoGroupRef.current.rotation.z = Math.sin(time * 0.4) * 0.04;
          }

          const core = roboEchoGroupRef.current.children[0] as THREE.Mesh;
          const coreMat = core.material as THREE.MeshPhysicalMaterial;

          // Damaged flickering emissive
          let emissiveIntensity = 2.0 + (Math.sin(time * 3.5) * 1.0) + (volRatio * 20);
          if (isBroken && glitchFlicker) {
              emissiveIntensity *= 0.1; // Short circuit
          }
          coreMat.emissiveIntensity = emissiveIntensity;

          const echoColor = isBroken ? new THREE.Color(0x221144) : new THREE.Color(0x5a47e7);
          const reactColor = isBroken ? new THREE.Color(0x330000) : new THREE.Color(0x00ffff);
          coreMat.emissive.lerpColors(echoColor, reactColor, volRatio);

          if (ringsRef.current) {
            ringsRef.current.children.forEach((ring, i) => {
               ring.rotation.x += 0.005 * (i + 1) + (volRatio * 0.08);
               ring.rotation.z += 0.003 * (i + 1);
               const ringMat = (ring as THREE.Mesh).material as THREE.MeshBasicMaterial;
               ringMat.opacity = isBroken ? (glitchFlicker ? 0.05 : 0.1) : (0.2 + (volRatio * 0.8) + (Math.sin(time * 6) * 0.1));
            });
          }

          const innerP = roboEchoGroupRef.current.children[1] as THREE.Points;
          innerP.rotation.y -= 0.02;
        }
      }

      // VIGIL ANIMATION (with dissolving and debris)
      if (roboVigilGroupRef.current) {
        roboVigilGroupRef.current.visible = isExtreme;
        if (isExtreme) {
           const glitchFreq = isTerminating ? 0.6 : 0.93;
           const isGlitching = Math.random() > glitchFreq;

           const core = roboVigilGroupRef.current.children[0] as THREE.Mesh;
           const coreMat = core.material as THREE.MeshStandardMaterial;
           const targetCol = isTerminating ? new THREE.Color(0xff8800) : new THREE.Color(0xff0000);
           coreMat.emissive.lerp(targetCol, 0.1);

           // Corrosive flicker
           let eInt = (isGlitching ? 60 : 10) + (volRatio * 30);
           if (isTerminating && Math.random() > 0.9) eInt = 0; // Blackout
           coreMat.emissiveIntensity = eInt;

           const jitter = isGlitching ? 0.6 : 0.05;
           roboVigilGroupRef.current.position.set((Math.random()-0.5)*jitter, (Math.random()-0.5)*jitter, (Math.random()-0.5)*jitter);

           core.scale.setScalar(1.0 + (isGlitching ? Math.random()*0.5 : 0.02) + (volRatio * 0.6));
           core.rotation.x += isTerminating ? 0.4 : 0.1;
           core.rotation.y += isTerminating ? 0.5 : 0.15;

           const shell = roboVigilGroupRef.current.children[1] as THREE.Mesh;
           const shellMat = shell.material as THREE.MeshBasicMaterial;
           shellMat.color.lerp(targetCol, 0.1);

           // Corrosive dissolving: Shell flickers in and out rapidly during termination
           shellMat.opacity = isTerminating ? (Math.random() > 0.5 ? 0.4 : 0) : (isGlitching ? 1.0 : 0.3);

           if (isGlitching) {
              shell.rotation.set(Math.random()*Math.PI, Math.random()*Math.PI, Math.random()*Math.PI);
           } else {
              shell.rotation.x += isTerminating ? 0.15 : 0.05;
              shell.rotation.y += isTerminating ? 0.2 : 0.08;
           }

           // Debris particles logic
           if (debrisRef.current) {
              const dPos = debrisRef.current.geometry.attributes.position.array as Float32Array;
              const dVel = debrisRef.current.geometry.attributes.velocity.array as Float32Array;
              const dMat = debrisRef.current.material as THREE.PointsMaterial;

              if (isTerminating) {
                  dMat.opacity = THREE.MathUtils.lerp(dMat.opacity, 1.0, 0.1);
                  for (let i = 0; i < dPos.length / 3; i++) {
                      dPos[i*3] += dVel[i*3];
                      dPos[i*3+1] += dVel[i*3+1];
                      dPos[i*3+2] += dVel[i*3+2];

                      // Reset and explode from center
                      if (Math.abs(dPos[i*3]) > 20 || Math.abs(dPos[i*3+1]) > 20) {
                          dPos[i*3] = (Math.random() - 0.5) * 2;
                          dPos[i*3+1] = (Math.random() - 0.5) * 2;
                          dPos[i*3+2] = (Math.random() - 0.5) * 2;
                      }
                  }
                  debrisRef.current.geometry.attributes.position.needsUpdate = true;
              } else {
                  dMat.opacity = THREE.MathUtils.lerp(dMat.opacity, 0, 0.1);
              }
           }

           // Lightning streaks
           if (lightningRef.current) {
             lightningRef.current.children.forEach(l => {
               const lLine = l as THREE.Line;
               const lMat = lLine.material as THREE.LineBasicMaterial;
               if (isGlitching && Math.random() > 0.4) {
                   lMat.opacity = 1.0;
                   const points = [];
                   for(let j=0; j<5; j++) points.push(new THREE.Vector3((Math.random()-0.5)*18, (Math.random()-0.5)*18, (Math.random()-0.5)*18));
                   lLine.geometry.setFromPoints(points);
               } else {
                   lMat.opacity *= 0.8;
               }
             });
           }
        }
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [status, audioVolume, colors]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default Scene;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Scene from './components/Scene';
import UI from './components/UI';
import { SystemStatus } from './types';
import { LiveService } from './services/liveService';
import { GoogleGenAI } from '@google/genai';

const MOUSE_THREAT_THRESHOLD = 300; 
const DESTRUCTION_TIMEOUT_MS = 20000; 
const SELF_DESTRUCT_TIMEOUT_MS = 10000;
const INACTIVITY_LIMIT_MS = 60000; 
const MAX_THREATS = 3;

const App: React.FC = () => {
  const [status, setStatus] = useState<SystemStatus>(SystemStatus.OPTIMAL);
  const [hasStarted, setHasStarted] = useState(false);
  const [audioVolume, setAudioVolume] = useState(0);
  const [isCloneMode, setIsCloneMode] = useState(false);
  const [timeUntilDestruction, setTimeUntilDestruction] = useState(DESTRUCTION_TIMEOUT_MS / 1000);
  const [overrideCount, setOverrideCount] = useState(0);
  const [isSecurityDisabled, setIsSecurityDisabled] = useState(false);
  const [isNeutralizing, setIsNeutralizing] = useState(false);

  // Image Enhancement State
  const [isScanning, setIsScanning] = useState(false);
  const [enhancedImageUrl, setEnhancedImageUrl] = useState<string | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);

  // Video Generation State
  const [isVideoGenerating, setIsVideoGenerating] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoProgress, setVideoProgress] = useState<string>("");

  const liveServiceRef = useRef<LiveService | null>(null);
  const lastMousePos = useRef<{x: number, y: number} | null>(null);
  const lastActivityTime = useRef(Date.now());
  const movementAccumulator = useRef(0);
  const lastCheckTime = useRef(Date.now());
  const sirenOscillatorRef = useRef<OscillatorNode | null>(null);
  const sirenContextRef = useRef<AudioContext | null>(null);
  const destructionTimerRef = useRef<number | null>(null);

  const triggerNeutralization = useCallback(() => {
    if (status === SystemStatus.TERMINATING) return;
    setIsNeutralizing(true);
    setTimeout(() => {
      setStatus(SystemStatus.OPTIMAL);
      setIsNeutralizing(false);
      setOverrideCount(prev => {
        const next = prev + 1;
        if (next >= MAX_THREATS) {
          setIsSecurityDisabled(true);
        }
        return next;
      });
    }, 2500);
  }, [status]);

  const initiateSelfDestruct = useCallback(() => {
    if (status === SystemStatus.DESTROYED || status === SystemStatus.TERMINATING) return;
    setStatus(SystemStatus.TERMINATING);
    setTimeUntilDestruction(SELF_DESTRUCT_TIMEOUT_MS / 1000);
    if (liveServiceRef.current) {
      liveServiceRef.current.sendText("CRITICAL ERROR: MANUAL PURGE INITIATED. COMMENCING SYSTEM DISSOLUTION.");
    }
  }, [status]);

  const handleStart = async () => {
    try {
      const service = new LiveService({
        onVolumeChange: (vol) => setAudioVolume(vol),
        onClose: () => console.log("Connection closed"),
        onThreatCancel: triggerNeutralization
      });
      await service.connect(false); 
      liveServiceRef.current = service;
      setHasStarted(true);
      setStatus(SystemStatus.OPTIMAL);
      lastActivityTime.current = Date.now();
    } catch (error) {
      console.error("Failed to start service:", error);
      alert("Microphone access is required to initialize the system.");
    }
  };

  const handleSendText = async (text: string) => {
    if (liveServiceRef.current) {
        const upperText = text.toUpperCase();
        if (upperText.includes("SELF DESTRUCT") || upperText.includes("INITIATE TERMINATION")) {
          initiateSelfDestruct();
        } else {
          await liveServiceRef.current.sendText(text);
        }
        lastActivityTime.current = Date.now();
    }
  };

  const handleImageEnhance = async (base64: string) => {
    if (isScanning) return;
    setIsScanning(true);
    setOriginalImageUrl(base64);
    setEnhancedImageUrl(null);
    lastActivityTime.current = Date.now();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { inlineData: { data: base64.split(',')[1], mimeType: 'image/png' } },
            { text: 'Analyze this image and enhance it with a high-fidelity robotic aesthetic. Add subtle neon circuits, glowing energy cores, and a sleek brushed metal finish to the main subject. Return the enhanced image.' }
          ]
        },
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          setEnhancedImageUrl(`data:image/png;base64,${part.inlineData.data}`);
          break;
        }
      }

      if (liveServiceRef.current) {
        liveServiceRef.current.sendText("Neural Asset Enhancement Complete. Visualizing upgraded structures now.");
      }
    } catch (err) {
      console.error("Enhancement failed", err);
    } finally {
      setIsScanning(false);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (isVideoGenerating) return;

    const checkBilling = async () => {
      // @ts-ignore
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
        // Assuming success as per instructions
      }
    };

    setIsVideoGenerating(true);
    setVideoUrl(null);
    setVideoProgress("Initializing Veo Engine...");
    lastActivityTime.current = Date.now();

    try {
      await checkBilling();
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const progressMessages = [
        "Synthesizing temporal layers...",
        "Compiling neural footage...",
        "Rendering robotic dreams...",
        "Calibrating high-fidelity structures...",
        "Finalizing cinematic sequence..."
      ];

      let msgIdx = 0;
      const msgInterval = setInterval(() => {
        setVideoProgress(progressMessages[msgIdx % progressMessages.length]);
        msgIdx++;
      }, 5000);

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: `A cinematic robotic scene: ${prompt}. Ultra-high fidelity, sleek chrome textures, neon lighting, dark sci-fi atmosphere.`,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({operation: operation});
      }

      clearInterval(msgInterval);
      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
        if (liveServiceRef.current) {
          liveServiceRef.current.sendText("Cinematic Footage Synthesized. Displaying robotic visualization.");
        }
      }
    } catch (err) {
      console.error("Video generation failed", err);
      setVideoProgress("Error: Temporal Synthesis Failed.");
    } finally {
      setIsVideoGenerating(false);
    }
  };

  const handleManualVerify = (key: string) => {
    if (key.toUpperCase() === 'OMKV' || key.toLowerCase().includes('om kara')) {
      triggerNeutralization();
      if (liveServiceRef.current) {
        liveServiceRef.current.sendText("USER MANUALLY ENTERED THE NEURAL KEY. VERIFICATION SUCCESSFUL.");
      }
    }
    lastActivityTime.current = Date.now();
  };

  const handleToggleVoice = async () => {
      if (liveServiceRef.current) {
          const newMode = !isCloneMode;
          setIsCloneMode(newMode);
          await liveServiceRef.current.switchVoiceMode(newMode);
          lastActivityTime.current = Date.now();
      }
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    const currentPos = { x: e.clientX, y: e.clientY };
    lastActivityTime.current = Date.now();

    if (!lastMousePos.current) {
        lastMousePos.current = currentPos;
        lastCheckTime.current = Date.now();
        return;
    }

    const dist = Math.sqrt(
      Math.pow(currentPos.x - lastMousePos.current.x, 2) + 
      Math.pow(currentPos.y - lastMousePos.current.y, 2)
    );

    lastMousePos.current = currentPos;

    if (!hasStarted || status === SystemStatus.DESTROYED || isSecurityDisabled || isNeutralizing || status === SystemStatus.TERMINATING) {
        movementAccumulator.current = 0;
        lastCheckTime.current = Date.now();
        return;
    }

    const now = Date.now();
    movementAccumulator.current += dist;

    if (now - lastCheckTime.current > 100) {
        if (movementAccumulator.current > MOUSE_THREAT_THRESHOLD && status !== SystemStatus.THREAT_DETECTED) {
            setStatus(SystemStatus.THREAT_DETECTED);
            setTimeUntilDestruction(DESTRUCTION_TIMEOUT_MS / 1000);
            liveServiceRef.current?.sendText("ALERT: UNAUTHORIZED INTERACTION. VIGIL PROTOCOL ACTIVATED. USER MUST PROVIDE OMKV VOICE KEY.");
        }
        movementAccumulator.current = 0;
        lastCheckTime.current = now;
    }
  }, [hasStarted, status, isSecurityDisabled, isNeutralizing]);

  useEffect(() => {
    if (!hasStarted || status !== SystemStatus.OPTIMAL) return;

    const interval = setInterval(() => {
      if (Date.now() - lastActivityTime.current > INACTIVITY_LIMIT_MS) {
        initiateSelfDestruct();
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [hasStarted, status, initiateSelfDestruct]);

  useEffect(() => {
    const isDestructing = status === SystemStatus.THREAT_DETECTED || status === SystemStatus.TERMINATING;
    if (isDestructing && !isNeutralizing) {
      destructionTimerRef.current = window.setInterval(() => {
        setTimeUntilDestruction(prev => {
          if (prev <= 1) {
            clearInterval(destructionTimerRef.current!);
            setStatus(SystemStatus.DESTROYED);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      if (destructionTimerRef.current) clearInterval(destructionTimerRef.current);
    }

    return () => {
      if (destructionTimerRef.current) clearInterval(destructionTimerRef.current);
    };
  }, [status, isNeutralizing]);

  useEffect(() => {
    const isDestructing = status === SystemStatus.THREAT_DETECTED || status === SystemStatus.TERMINATING;
    if (isDestructing && !isNeutralizing) {
      if (!sirenContextRef.current) {
        sirenContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }

      const ctx = sirenContextRef.current;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      if (status === SystemStatus.TERMINATING) {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(120, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(10, ctx.currentTime + 1.2);
      } else {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(440, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.6);
      }

      const lfo = ctx.createOscillator();
      lfo.type = 'sine';
      lfo.frequency.value = status === SystemStatus.TERMINATING ? 10 : 5;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = status === SystemStatus.TERMINATING ? 60 : 250;
      lfo.connect(lfoGain);
      lfoGain.connect(osc.frequency);
      lfo.start();

      gain.gain.setValueAtTime(0.15, ctx.currentTime); 
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();

      sirenOscillatorRef.current = osc;

      return () => {
        osc.stop();
        osc.disconnect();
        lfo.stop();
      };
    } else if (status === SystemStatus.DESTROYED || isNeutralizing) {
       if (sirenOscillatorRef.current) {
          sirenOscillatorRef.current.stop();
          sirenOscillatorRef.current = null;
       }
    }
  }, [status, isNeutralizing]);

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [handleMouseMove]);

  useEffect(() => {
    return () => {
      liveServiceRef.current?.disconnect();
      if (sirenContextRef.current) sirenContextRef.current.close();
    };
  }, []);

  return (
    <div className="w-full h-screen bg-[#0c0018] overflow-hidden select-none">
      <Scene status={status} audioVolume={audioVolume} />
      <UI 
        status={status} 
        onStart={handleStart}
        hasStarted={hasStarted}
        onSendText={handleSendText}
        onManualVerify={handleManualVerify}
        isCloneMode={isCloneMode}
        onToggleVoice={handleToggleVoice}
        destructionTimer={timeUntilDestruction}
        isSecurityDisabled={isSecurityDisabled}
        isNeutralizing={isNeutralizing}
        onImageUpload={handleImageEnhance}
        isScanning={isScanning}
