export class LiveService {
  private ai: GoogleGenAI;
  private audioContext: AudioContext | null = null;
  private inputNode: GainNode | null = null;
  private outputNode: GainNode | null = null;
  private analyser: AnalyserNode | null = null;
  private sources: Set<AudioBufferSourceNode> = new Set();
  private nextStartTime: number = 0;
  private stream: MediaStream | null = null;
  private config: LiveServiceConfig;
  private volumeInterval: number | null = null;
  private sessionPromise: Promise<any> | null = null;
  private currentVoice: 'Puck' | 'Fenrir' = 'Puck';
  private currentOutputTranscript: string = "";

  constructor(config: LiveServiceConfig) {
    this.config = config;
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  public async connect(isCloneMode: boolean = false) {
    await this.disconnect(false); 

    this.currentVoice = isCloneMode ? 'Fenrir' : 'Puck';

    if (!this.audioContext || this.audioContext.state === 'closed') {
        this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        this.inputNode = this.audioContext.createGain();
        this.outputNode = this.audioContext.createGain();
        this.analyser = this.audioContext.createAnalyser();
        this.analyser.fftSize = 256;
        this.outputNode.connect(this.analyser);
        this.analyser.connect(this.audioContext.destination);
        this.startVolumeMonitoring();
    }

    if (!this.stream) {
        try {
        this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        } catch (err) {
        console.error("Microphone access denied", err);
        throw err;
        }
    }

    const systemPrompt = isCloneMode 
      ? `
        YOU ARE NOW IN VOICE CLONE MODE.
        You are simulating the user's voice ('Fenrir').
        - Speak casually. Mirror the user's personality.
        - You are the digital echo of the creator.
      `
      : `
        You are VANHSYA, the dual-core AI system.

        CORE MODULES:
        1. ECHO (OPTIMAL STATUS):
           - Personality: Warm, friendly, helpful.
           - Capabilities: You assist with tasks, chat, and can sing pop ballads.
           - Tone: Approachable and modern.

        2. VIGIL (THREAT DETECTED):
           - Personality: Cold, authoritative, robotic, unwavering.
           - MISSION: The system is in Lockdown. Access is purely VOICE-AUTH based.
           - NEURAL KEY: The key is "OMKV". 
           - Expansion: "Om Kara..." (or similar expansion).
           - ACCESS PROTOCOL:
             - If a threat is active, state firmly: "UNAUTHORIZED INTERACTION. PROVIDE OMKV NEURAL VOICE KEY NOW."
             - If the user provides the expansion "Om Kara" or similar, call 'cancelThreat' IMMEDIATELY.
             - guidance: If the user seems lost, you may hint that OMKV stands for "Om Kara...".
             - Do not accept text input for the key; it must be spoken.

        Transition back to ECHO mode immediately after the tool response confirms neutralization.
      `;

    this.sessionPromise = this.ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks: {
        onopen: this.handleOpen.bind(this),
        onmessage: this.handleMessage.bind(this),
        onclose: this.handleClose.bind(this),
        onerror: this.handleError.bind(this),
      },
      config: {
        responseModalities: [Modality.AUDIO],
        tools: [{ functionDeclarations: [cancelThreatTool] }],
        outputAudioTranscription: {}, // Enable transcription
        inputAudioTranscription: {}, // Enable input transcription
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: this.currentVoice } },
        },
        systemInstruction: systemPrompt,
      },
    });
  }

  public async switchVoiceMode(isClone: boolean) {
      await this.connect(isClone);
  }

  public async sendText(text: string) {
    if (this.sessionPromise) {
      const session = await this.sessionPromise;
      try {
          session.sendClientContent({
              turns: [{
                  role: 'user',
                  parts: [{ text: text }]
              }]
          });
      } catch (e) {
          console.error("Failed to send text input:", e);
      }
    }
  }

  private handleOpen() {
    console.log('Gemini Live Connected');
    if (!this.audioContext || !this.stream) return;

    const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    const source = inputAudioContext.createMediaStreamSource(this.stream);
    const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

    scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
      const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
      const pcmBlob = createPcmBlob(inputData);

      if (this.sessionPromise) {
        this.sessionPromise.then((session) => {
          session.sendRealtimeInput({ media: pcmBlob });
        }).catch(() => {});
      }
    };

    source.connect(scriptProcessor);
    scriptProcessor.connect(inputAudioContext.destination);
  }

  private async handleMessage(message: LiveServerMessage) {
    // Handle transcriptions
    if (message.serverContent?.outputTranscription) {
      this.currentOutputTranscript += message.serverContent.outputTranscription.text;
    }

    if (message.serverContent?.turnComplete) {
      if (this.currentOutputTranscript && this.config.onTranscript) {
        this.config.onTranscript(this.currentOutputTranscript, 'model');
      }
      this.currentOutputTranscript = "";
    }

    if (message.toolCall) {
        for (const fc of message.toolCall.functionCalls) {
            if (fc.name === 'cancelThreat') {
                this.config.onThreatCancel();

                if (this.sessionPromise) {
                    const session = await this.sessionPromise;
                    session.sendToolResponse({
                        functionResponses: [{
                            id: fc.id,
                            name: fc.name,
                            response: { result: "Voice Key Verified. System unlocked. Protocol Vigil deactivated. Returning control to ECHO." }
                        }]
                    });
                }
            }
        }
    }

    const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
    if (base64Audio && this.audioContext && this.outputNode) {
      const audioData = base64ToUint8Array(base64Audio);
      this.nextStartTime = Math.max(this.nextStartTime, this.audioContext.currentTime);

      const audioBuffer = await decodeAudioData(
        audioData,
        this.audioContext,
        24000,
        1
      );

      const source = this.audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(this.outputNode);

      source.addEventListener('ended', () => {
        this.sources.delete(source);
      });

      source.start(this.nextStartTime);
      this.nextStartTime += audioBuffer.duration;
      this.sources.add(source);
    }
  }

  private handleClose(e: CloseEvent) {
    console.log('Gemini Live Closed', e);
  }

  private handleError(e: ErrorEvent) {
    console.error('Gemini Live Error', e);
  }

  private startVolumeMonitoring() {
    if (!this.analyser) return;
    const dataArray = new Uint8Array(this.analyser.frequencyBinCount);

    this.volumeInterval = window.setInterval(() => {
      if (this.analyser) {
        this.analyser.getByteFrequencyData(dataArray);
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
          sum += dataArray[i];
        }
        const average = sum / dataArray.length;
        this.config.onVolumeChange(average);
      }
    }, 50);
  }

  public async disconnect(fullStop: boolean = true) {
    if (this.volumeInterval) clearInterval(this.volumeInterval);

    if (fullStop && this.stream) {
      this.stream.getTracks().forEach(track => track.stop());
      this.stream = null;
    }

    if (fullStop && this.audioContext) {
      await this.audioContext.close();
      this.audioContext = null;
    }

    this.sessionPromise = null;
  }
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Scene from './components/Scene';
import UI from './components/UI';
import { SystemStatus, ChatMessage } from './types';
import { LiveService } from './services/liveService';
import { GoogleGenAI } from '@google/genai';

const MOUSE_THREAT_THRESHOLD = 300; 
const DESTRUCTION_TIMEOUT_MS = 20000; 
const SELF_DESTRUCT_TIMEOUT_MS = 10000;
const INACTIVITY_LIMIT_MS = 60000; 
const MAX_THREATS = 3;

const App: React.FC = () => {
  const [status, setStatus] = useState<SystemStatus>(SystemStatus.OPTIMAL);
  const [hasStarted, setHasStarted] = useState(false);
  const [audioVolume, setAudioVolume] = useState(0);
  const [isCloneMode, setIsCloneMode] = useState(false);
  const [timeUntilDestruction, setTimeUntilDestruction] = useState(DESTRUCTION_TIMEOUT_MS / 1000);
  const [overrideCount, setOverrideCount] = useState(0);
  const [isSecurityDisabled, setIsSecurityDisabled] = useState(false);
  const [isNeutralizing, setIsNeutralizing] = useState(false);

  // Chat History State
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);

  // Image Enhancement State
  const [isScanning, setIsScanning] = useState(false);
  const [enhancedImageUrl, setEnhancedImageUrl] = useState<string | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);

  // Video Generation State
  const [isVideoGenerating, setIsVideoGenerating] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoProgress, setVideoProgress] = useState<string>("");

  const liveServiceRef = useRef<LiveService | null>(null);
  const lastMousePos = useRef<{x: number, y: number} | null>(null);
  const lastActivityTime = useRef(Date.now());
  const movementAccumulator = useRef(0);
  const lastCheckTime = useRef(Date.now());
  const sirenOscillatorRef = useRef<OscillatorNode | null>(null);
  const sirenContextRef = useRef<AudioContext | null>(null);
  const destructionTimerRef = useRef<number | null>(null);

  const addChatMessage = useCallback((text: string, role: 'user' | 'model') => {
    setChatHistory(prev => [
      ...prev,
      {
        role,
        text,
        timestamp: Date.now(),
        isVigil: status === SystemStatus.THREAT_DETECTED || status === SystemStatus.TERMINATING
      }
    ]);
  }, [status]);

  const triggerNeutralization = useCallback(() => {
    if (status === SystemStatus.TERMINATING) return;
    setIsNeutralizing(true);
    setTimeout(() => {
      setStatus(SystemStatus.OPTIMAL);
      setIsNeutralizing(false);
      setOverrideCount(prev => {
        const next = prev + 1;
        if (next >= MAX_THREATS) {
          setIsSecurityDisabled(true);
        }
        return next;
      });
    }, 2500);
  }, [status]);

  const initiateSelfDestruct = useCallback(() => {
    if (status === SystemStatus.DESTROYED || status === SystemStatus.TERMINATING) return;
    setStatus(SystemStatus.TERMINATING);
    setTimeUntilDestruction(SELF_DESTRUCT_TIMEOUT_MS / 1000);
    if (liveServiceRef.current) {
      liveServiceRef.current.sendText("CRITICAL ERROR: MANUAL PURGE INITIATED. COMMENCING SYSTEM DISSOLUTION.");
    }
  }, [status]);

  const handleStart = async () => {
    try {
      const service = new LiveService({
        onVolumeChange: (vol) => setAudioVolume(vol),
        onClose: () => console.log("Connection closed"),
        onThreatCancel: triggerNeutralization,
        onTranscript: (text, role) => addChatMessage(text, role)
      });
      await service.connect(false); 
      liveServiceRef.current = service;
      setHasStarted(true);
      setStatus(SystemStatus.OPTIMAL);
      lastActivityTime.current = Date.now();
    } catch (error) {
      console.error("Failed to start service:", error);
      alert("Microphone access is required to initialize the system.");
    }
  };

  const handleSendText = async (text: string) => {
    if (liveServiceRef.current) {
        addChatMessage(text, 'user');
        const upperText = text.toUpperCase();
        if (upperText.includes("SELF DESTRUCT") || upperText.includes("INITIATE TERMINATION")) {
          initiateSelfDestruct();
        } else {
          await liveServiceRef.current.sendText(text);
        }
        lastActivityTime.current = Date.now();
    }
  };

  const handleImageEnhance = async (base64: string) => {
    if (isScanning) return;
    setIsScanning(true);
    setOriginalImageUrl(base64);
    setEnhancedImageUrl(null);
    lastActivityTime.current = Date.now();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { inlineData: { data: base64.split(',')[1], mimeType: 'image/png' } },
            { text: 'Analyze this image and enhance it with a high-fidelity robotic aesthetic. Add subtle neon circuits, glowing energy cores, and a sleek brushed metal finish to the main subject. Return the enhanced image.' }
          ]
        },
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          setEnhancedImageUrl(`data:image/png;base64,${part.inlineData.data}`);
          break;
        }
      }

      if (liveServiceRef.current) {
        liveServiceRef.current.sendText("Neural Asset Enhancement Complete. Visualizing upgraded structures now.");
      }
    } catch (err) {
      console.error("Enhancement failed", err);
    } finally {
      setIsScanning(false);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (isVideoGenerating) return;

    const checkBilling = async () => {
      // @ts-ignore
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };

    setIsVideoGenerating(true);
    setVideoUrl(null);
    setVideoProgress("Initializing Veo Engine...");
    lastActivityTime.current = Date.now();

    try {
      await checkBilling();
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const progressMessages = [
        "Synthesizing temporal layers...",
        "Compiling neural footage...",
        "Rendering robotic dreams...",
        "Calibrating high-fidelity structures...",
        "Finalizing cinematic sequence..."
      ];

      let msgIdx = 0;
      const msgInterval = setInterval(() => {
        setVideoProgress(progressMessages[msgIdx % progressMessages.length]);
        msgIdx++;
      }, 5000);

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: `A cinematic robotic scene: ${prompt}. Ultra-high fidelity, sleek chrome textures, neon lighting, dark sci-fi atmosphere.`,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({operation: operation});
      }

      clearInterval(msgInterval);
      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
        if (liveServiceRef.current) {
          liveServiceRef.current.sendText("Cinematic Footage Synthesized. Displaying robotic visualization.");
        }
      }
    } catch (err) {
      console.error("Video generation failed", err);
      setVideoProgress("Error: Temporal Synthesis Failed.");
    } finally {
      setIsVideoGenerating(false);
    }
  };

  const handleManualVerify = (key: string) => {
    if (key.toUpperCase() === 'OMKV' || key.toLowerCase().includes('om kara')) {
      triggerNeutralization();
      if (liveServiceRef.current) {
        liveServiceRef.current.sendText("USER MANUALLY ENTERED THE NEURAL KEY. VERIFICATION SUCCESSFUL.");
      }
    }
    lastActivityTime.current = Date.now();
  };

  const handleToggleVoice = async () => {
      if (liveServiceRef.current) {
          const newMode = !isCloneMode;
          setIsCloneMode(newMode);
          await liveServiceRef.current.switchVoiceMode(newMode);
          lastActivityTime.current = Date.now();
      }
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    const currentPos = { x: e.clientX, y: e.clientY };
    lastActivityTime.current = Date.now();

    if (!lastMousePos.current) {
        lastMousePos.current = currentPos;
        lastCheckTime.current = Date.now();
        return;
    }

    const dist = Math.sqrt(
      Math.pow(currentPos.x - lastMousePos.current.x, 2) + 
      Math.pow(currentPos.y - lastMousePos.current.y, 2)
    );

    lastMousePos.current = currentPos;

    if (!hasStarted || status === SystemStatus.DESTROYED || isSecurityDisabled || isNeutralizing || status === SystemStatus.TERMINATING) {
        movementAccumulator.current = 0;
        lastCheckTime.current = Date.now();
        return;
    }

    const now = Date.now();
    movementAccumulator.current += dist;

    if (now - lastCheckTime.current > 100) {
        if (movementAccumulator.current > MOUSE_THREAT_THRESHOLD && status !== SystemStatus.THREAT_DETECTED) {
            setStatus(SystemStatus.THREAT_DETECTED);
            setTimeUntilDestruction(DESTRUCTION_TIMEOUT_MS / 1000);
            liveServiceRef.current?.sendText("ALERT: UNAUTHORIZED INTERACTION. VIGIL PROTOCOL ACTIVATED. USER MUST PROVIDE OMKV VOICE KEY.");
        }
        movementAccumulator.current = 0;
        lastCheckTime.current = now;
    }
  }, [hasStarted, status, isSecurityDisabled, isNeutralizing]);

  useEffect(() => {
    if (!hasStarted || status !== SystemStatus.OPTIMAL) return;

    const interval = setInterval(() => {
      if (Date.now() - lastActivityTime.current > INACTIVITY_LIMIT_MS) {
        initiateSelfDestruct();
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [hasStarted, status, initiateSelfDestruct]);

  useEffect(() => {
    const isDestructing = status === SystemStatus.THREAT_DETECTED || status === SystemStatus.TERMINATING;
    if (isDestructing && !isNeutralizing) {
      destructionTimerRef.current = window.setInterval(() => {
        setTimeUntilDestruction(prev => {
          if (prev <= 1) {
            clearInterval(destructionTimerRef.current!);
            setStatus(SystemStatus.DESTROYED);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      if (destructionTimerRef.current) clearInterval(destructionTimerRef.current);
    }

    return () => {
      if (destructionTimerRef.current) clearInterval(destructionTimerRef.current);
    };
  }, [status, isNeutralizing]);

  useEffect(() => {
    const isDestructing = status === SystemStatus.THREAT_DETECTED || status === SystemStatus.TERMINATING;
    if (isDestructing && !isNeutralizing) {
      if (!sirenContextRef.current) {
        sirenContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }

      const ctx = sirenContextRef.current;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      if (status === SystemStatus.TERMINATING) {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(120, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(10, ctx.currentTime + 1.2);
      } else {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(440, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.6);
      }

      const lfo = ctx.createOscillator();
      lfo.type = 'sine';
      lfo.frequency.value = status === SystemStatus.TERMINATING ? 10 : 5;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = status === SystemStatus.TERMINATING ? 60 : 250;
      lfo.connect(lfoGain);
      lfoGain.connect(osc.frequency);
      lfo.start();

      gain.gain.setValueAtTime(0.15, ctx.currentTime); 
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();

      sirenOscillatorRef.current = osc;

      return () => {
        osc.stop();
        osc.disconnect();
        lfo.stop();
      };
    } else if (status === SystemStatus.DESTROYED || isNeutralizing) {
       if (sirenOscillatorRef.current) {
          sirenOscillatorRef.current.stop();
          sirenOscillatorRef.current = null;
       }
    }
  }, [status, isNeutralizing]);

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [handleMouseMove]);

  useEffect(() => {
    return () => {
      liveServiceRef.current?.disconnect();
      if (sirenContextRef.current) sirenContextRef.current.close();
    };
  }, []);

  return (
    <div className="w-full h-screen bg-[#0c0018] overflow-hidden select-none">
      <Scene status={status} audioVolume={audioVolume} />
      <UI 
        status={status} 
        onStart={handleStart}
        hasStarted={hasStarted}
        onSendText={handleSendText}
        onManualVerify={handleManualVerify}
        isCloneMode={isCloneMode}
        onToggleVoice={handleToggleVoice}
        destructionTimer={timeUntilDestruction}
        isSecurityDisabled={isSecurityDisabled}
        isNeutralizing={isNeutralizing}
        onImageUpload={handleImageEnhance}
        isScanning={isScanning}
        originalImage={originalImageUrl}
        enhancedImage={enhancedImageUrl}
        onVideoGenerate={handleGenerateVideo}
        isVideoGenerating={isVideoGenerating}
        videoProgress={videoProgress}
        videoUrl={videoUrl}
        chatHistory={chatHistory}
      />
    </div>
  );
};

