  if (isDestroyed) {
      return (
          <div className="fixed inset-0 bg-black z-[200] flex items-center justify-center flex-col">
              <div className="text-red-900 font-mono text-6xl font-black tracking-tighter mb-4 animate-pulse">
                  SYSTEM PURGED
              </div>
              <div className="text-red-900 font-mono text-sm tracking-[1em]">
                  NO CONNECTION
              </div>
