    : (isTerminating ? 'border-amber-500 text-amber-500 bg-amber-950/80'
    : (isSecurityDisabled ? 'bg-[#5a47e7]/30 border-[#5a47e7] text-white' : 'bg-black/50 border-[#5a47e7]/30 text-[#5a47e7]')));

  return (
    <>
      <div className={`fixed inset-0 z-[100] pointer-events-none border-2 transition-all duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500/50 animate-pulse' : (isTerminating ? 'border-amber-500/50 animate-pulse' : 'border-[#5a47e7]/20'))}`} />

      {/* HUD Corners */}
      <div className="fixed inset-6 pointer-events-none z-[100]">
        <div className={`absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
        <div className={`absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
        <div className={`absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
        <div className={`absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 transition-colors duration-500 ${isNeutralizing ? 'border-white' : (isThreat ? 'border-red-500' : (isTerminating ? 'border-amber-500' : 'border-[#5a47e7]'))}`} />
      </div>

      {/* Top Header */}
      <div className="fixed top-10 left-10 z-[110] flex flex-col gap-3">
         <div className={`flex items-center text-lg tracking-widest uppercase font-bold font-mono p-3 rounded backdrop-blur-md border transition-all duration-300 ${statusColorClass}`}>
            <StatusIcon status={status} isNeutralizing={isNeutralizing} />
