    const scene = new THREE.Scene();
    sceneRef.current = scene;
    const camera = new THREE.PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 20;
    cameraRef.current = camera;
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const bgGeometry = new THREE.PlaneGeometry(120, 120);
    const bgMaterial = new THREE.ShaderMaterial({
      vertexShader, fragmentShader,
      uniforms: { uTime: { value: 0 }, uColorA: { value: new THREE.Color(colors.optimal.a) }, uColorB: { value: new THREE.Color(colors.optimal.b) }, uIntensity: { value: 0.6 } },
      depthWrite: false, 
    });
    const backgroundMesh = new THREE.Mesh(bgGeometry, bgMaterial);
    backgroundMesh.position.z = -25;
    scene.add(backgroundMesh);
    backgroundMaterialRef.current = bgMaterial;

    const interactionLight = new THREE.PointLight(0xffffff, 0, 50);
    scene.add(interactionLight);
    interactionLightRef.current = interactionLight;

    // --- ECHO ---
    const echoGroup = new THREE.Group();
    const coreMat = new THREE.MeshPhysicalMaterial({ color: 0x5a47e7, emissive: 0x5a47e7, emissiveIntensity: 3, roughness: 0.1, metalness: 0.9, transparent: true, opacity: 0.9 });
    const core = new THREE.Mesh(new THREE.SphereGeometry(2.4, 64, 64), coreMat);
    echoGroup.add(core);
    const shellMat = new THREE.MeshPhysicalMaterial({ color: 0xffffff, transmission: 0.98, thickness: 2.0, ior: 1.45, roughness: 0.0, transparent: true, opacity: 0.2 });
    echoGroup.add(new THREE.Mesh(new THREE.SphereGeometry(3.5, 64, 64), shellMat));
    const rings = new THREE.Group();
    for (let i = 0; i < 4; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(5.0 + i * 1.2, 0.02, 16, 100), new THREE.MeshBasicMaterial({ color: 0x5a47e7, transparent: true, opacity: 0.3 }));
      ring.rotation.x = Math.random() * Math.PI;
      rings.add(ring);
    }
    echoGroup.add(rings);
    ringsRef.current = rings;
    scene.add(echoGroup);
    roboEchoGroupRef.current = echoGroup;

    // --- VIGIL ---
    const vigilGroup = new THREE.Group();
    const vigilCoreMat = new THREE.MeshStandardMaterial({ color: 0x000000, emissive: 0xff0000, emissiveIntensity: 10, flatShading: true });
    vigilGroup.add(new THREE.Mesh(new THREE.IcosahedronGeometry(3.2, 0), vigilCoreMat));
    vigilGroup.visible = false;
    scene.add(vigilGroup);
    roboVigilGroupRef.current = vigilGroup;

    // --- AIR PARTICLES ---
    const airCount = 1500;
    const airGeo = new THREE.BufferGeometry();
    const airPos = new Float32Array(airCount * 3);
    for(let i=0; i<airCount; i++) {
        airPos[i*3] = (Math.random() - 0.5) * 40;
        airPos[i*3+1] = (Math.random() - 0.5) * 40;
        airPos[i*3+2] = (Math.random() - 0.5) * 40;
    }
    airGeo.setAttribute('position', new THREE.BufferAttribute(airPos, 3));
    const airPoints = new THREE.Points(airGeo, new THREE.PointsMaterial({ color: 0xffffff, size: 0.05, transparent: true, opacity: 0.2 }));
    scene.add(airPoints);
    airParticlesRef.current = airPoints;

    const onPointerDown = (event: MouseEvent | TouchEvent) => {
      const clientX = 'touches' in event ? event.touches[0].clientX : event.clientX;
      const clientY = 'touches' in event ? event.touches[0].clientY : event.clientY;
      mouse.x = (clientX / window.innerWidth) * 2 - 1;
      mouse.y = -(clientY / window.innerHeight) * 2 + 1;
      raycaster.setFromCamera(mouse, camera);
      const targets = status === SystemStatus.THREAT_DETECTED ? [roboVigilGroupRef.current] : [roboEchoGroupRef.current];
      const intersects = raycaster.intersectObjects(targets as any, true);
      if (intersects.length > 0) {
        onTouch();
        if (interactionLightRef.current) {
          interactionLightRef.current.position.copy(intersects[0].point);
          interactionLightRef.current.intensity = 20;
        }
      }
    };

    window.addEventListener('mousedown', onPointerDown);
    window.addEventListener('touchstart', onPointerDown);
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };
    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('mousedown', onPointerDown);
      window.removeEventListener('touchstart', onPointerDown);
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, [status, onTouch, colors, mouse, raycaster]);

  useEffect(() => {
    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);
      const time = Date.now() * 0.001;
      const volRatio = Math.min(audioVolume / 180, 1.0);

      if (backgroundMaterialRef.current) {
        backgroundMaterialRef.current.uniforms.uTime.value += 0.005 + (volRatio * 0.05);
        let targetA = colors.optimal.a; let targetB = colors.optimal.b;
        if (status === SystemStatus.THREAT_DETECTED) { targetA = colors.threat.a; targetB = colors.threat.b; }
        else if (status === SystemStatus.TERMINATING) { targetA = colors.terminating.a; targetB = colors.terminating.b; }
        backgroundMaterialRef.current.uniforms.uColorA.value.lerp(targetA, 0.05);
        backgroundMaterialRef.current.uniforms.uColorB.value.lerp(targetB, 0.05);
      }

      if (interactionLightRef.current) interactionLightRef.current.intensity *= 0.9;

      if (airParticlesRef.current) {
        const pos = airParticlesRef.current.geometry.attributes.position.array as Float32Array;
        for(let i=0; i<pos.length/3; i++){
          pos[i*3] += Math.sin(time + i) * 0.01;
          pos[i*3+1] += Math.cos(time + i) * 0.01;
        }
        airParticlesRef.current.geometry.attributes.position.needsUpdate = true;
      }

      if (roboEchoGroupRef.current && status !== SystemStatus.THREAT_DETECTED) {
        roboEchoGroupRef.current.visible = true;
        roboEchoGroupRef.current.rotation.y += 0.005 + volRatio * 0.1;
        const s = 1.0 + Math.sin(time * 2) * 0.05 + volRatio * 0.2;
        roboEchoGroupRef.current.scale.lerp(new THREE.Vector3(s, s, s), 0.1);
      }
      if (roboVigilGroupRef.current && status === SystemStatus.THREAT_DETECTED) {
        roboVigilGroupRef.current.visible = true;
        roboVigilGroupRef.current.rotation.x += 0.05;
        roboVigilGroupRef.current.rotation.y += 0.05;
      } else if (roboVigilGroupRef.current) {
        roboVigilGroupRef.current.visible = false;
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };
    animate();
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [status, audioVolume, colors]);

  return <div ref={mountRef} className="fixed inset-0 z-0" />;
};
export default Scene;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Scene from './components/Scene';
import UI from './components/UI';
import { SystemStatus, ChatMessage } from './types';
import { LiveService } from './services/liveService';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [status, setStatus] = useState<SystemStatus>(SystemStatus.OPTIMAL);
  const [hasStarted, setHasStarted] = useState(false);
  const [audioVolume, setAudioVolume] = useState(0);
  const [isCloneMode, setIsCloneMode] = useState(false);
  const [touchCount, setTouchCount] = useState(0);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);

  const [isScanning, setIsScanning] = useState(false);
  const [enhancedImageUrl, setEnhancedImageUrl] = useState<string | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [isVideoGenerating, setIsVideoGenerating] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoProgress, setVideoProgress] = useState("");

  const liveServiceRef = useRef<LiveService | null>(null);
  const neuralSynthRef = useRef<AudioContext | null>(null);

  const playNeuralPing = useCallback(() => {
    if (!neuralSynthRef.current) {
      neuralSynthRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    const ctx = neuralSynthRef.current;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(880 + Math.random() * 440, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(10, ctx.currentTime + 0.1);
    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.1);
  }, []);

  const handleTouch = useCallback(() => {
    setTouchCount(prev => prev + 1);
    playNeuralPing();
  }, [playNeuralPing]);

  const addChatMessage = useCallback((text: string, role: 'user' | 'model') => {
    setChatHistory(prev => [...prev, { role, text, timestamp: Date.now(), isVigil: status === SystemStatus.THREAT_DETECTED }]);
  }, [status]);

  const handleStart = async () => {
    try {
      const service = new LiveService({
        onVolumeChange: (vol) => setAudioVolume(vol),
        onClose: () => console.log("Connection closed"),
        onThreatCancel: () => setStatus(SystemStatus.OPTIMAL),
        onTranscript: (text, role) => addChatMessage(text, role)
      });
      await service.connect(false); 
      liveServiceRef.current = service;
      setHasStarted(true);
      setStatus(SystemStatus.OPTIMAL);
    } catch (error) {
      console.error("Start failed", error);
    }
  };

  const handleSendText = async (text: string) => {
    if (liveServiceRef.current) {
      addChatMessage(text, 'user');
      await liveServiceRef.current.sendText(text);
    }
  };

  const handleImageEnhance = async (base64: string) => {
    if (isScanning) return;
    setIsScanning(true);
    setOriginalImageUrl(base64);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ inlineData: { data: base64.split(',')[1], mimeType: 'image/png' } }, { text: 'Enhance this robotic subject.' }] }
      });
      const part = response.candidates[0].content.parts.find(p => p.inlineData);
      if (part) setEnhancedImageUrl(`data:image/png;base64,${part.inlineData.data}`);
    } catch (err) { console.error(err); }
    setIsScanning(false);
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (isVideoGenerating) return;
    setIsVideoGenerating(true);
    setVideoProgress("Initializing temporal layers...");
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let op = await ai.models.generateVideos({ model: 'veo-3.1-fast-generate-preview', prompt });
      while (!op.done) {
        await new Promise(r => setTimeout(r, 5000));
        op = await ai.operations.getVideosOperation({ operation: op });
      }
      const link = op.response?.generatedVideos?.[0]?.video?.uri;
      if (link) {
        const res = await fetch(`${link}&key=${process.env.API_KEY}`);
        setVideoUrl(URL.createObjectURL(await res.blob()));
      }
    } catch (err) { console.error(err); }
    setIsVideoGenerating(false);
  };

  return (
    <div className="w-full h-screen bg-[#0c0018] overflow-hidden select-none">
      <Scene status={status} audioVolume={audioVolume} onTouch={handleTouch} />
      <UI 
        status={status} onStart={handleStart} hasStarted={hasStarted} 
        onSendText={handleSendText} onManualVerify={() => setStatus(SystemStatus.OPTIMAL)}
        isCloneMode={isCloneMode} onToggleVoice={() => setIsCloneMode(!isCloneMode)}
        onImageUpload={handleImageEnhance} isScanning={isScanning}
        originalImage={originalImageUrl} enhancedImage={enhancedImageUrl}
        onVideoGenerate={handleGenerateVideo} isVideoGenerating={isVideoGenerating}
        videoProgress={videoProgress} videoUrl={videoUrl}
        chatHistory={chatHistory} touchCount={touchCount}
      />
    </div>
  );
};
export default App;

