import { GoogleGenAI, LiveServerMessage, Modality, FunctionDeclaration, Type } from '@google/genai';
import { createPcmBlob, decodeAudioData, base64ToUint8Array } from '../utils/audioUtils';
import { LiveServiceConfig, SessionMode } from '../types';

const cancelThreatTool: FunctionDeclaration = {
  name: 'cancelThreat',
  parameters: {
    type: Type.OBJECT,
    description: 'Restores public access mode.',
    properties: {
      keyPhrase: { type: Type.STRING }
    },
    required: ['keyPhrase']
  }
};

export class LiveService {
  private audioContext: AudioContext | null = null;
  private inputNode: GainNode | null = null;
  private outputNode: GainNode | null = null;
  private analyser: AnalyserNode | null = null;
  private sources: Set<AudioBufferSourceNode> = new Set();
  private nextStartTime: number = 0;
  private stream: MediaStream | null = null;
  private config: LiveServiceConfig;
  private volumeInterval: number | null = null;
  private sessionPromise: Promise<any> | null = null;
  private currentMode: SessionMode = SessionMode.PUBLIC;
  private currentOutputTranscript: string = "";
  private currentInputTranscript: string = "";

  constructor(config: LiveServiceConfig) {
    this.config = config;
  }

  public async connect(mode: SessionMode = SessionMode.PUBLIC) {
    await this.disconnect(false); 
    this.currentMode = mode;

    if (!this.audioContext || this.audioContext.state === 'closed') {
        this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        this.inputNode = this.audioContext.createGain();
        this.outputNode = this.audioContext.createGain();
        this.analyser = this.audioContext.createAnalyser();
        this.analyser.fftSize = 256;
        this.outputNode.connect(this.analyser);
        this.analyser.connect(this.audioContext.destination);
        this.startVolumeMonitoring();
    }

    if (!this.stream) {
        try {
          this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        } catch (err) {
          console.error("Mic denied", err);
          throw err;
        }
    }

    const publicPrompt = `YOU ARE ECHO (PUBLIC CORE). 
    - Tone: Friendly, creative, casual, helpful.
    - Focus: Artistic generation, general chat, assisting the user with daily tasks.
    - Voice: Puck (Youthful/Clear).`;

    const privatePrompt = `YOU ARE VIGIL (PRIVATE CORE - HIGH CLEARANCE). 
    - Tone: Authoritative, cold, strictly professional, protective.
    - Focus: System integrity, deep-level data analysis, security protocols.
    - Voice: Fenrir (Deep/Resonant).
    - Rule: Only discuss sensitive data if the user exhibits high 'Neural Sync'.`;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    this.sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks: {
        onopen: this.handleOpen.bind(this),
        onmessage: this.handleMessage.bind(this),
        onclose: this.handleClose.bind(this),
        onerror: (e) => console.error(e),
      },
      config: {
        responseModalities: [Modality.AUDIO],
        tools: [{ functionDeclarations: [cancelThreatTool] }],
        outputAudioTranscription: {},
        inputAudioTranscription: {},
        speechConfig: {
          voiceConfig: { 
            prebuiltVoiceConfig: { 
              voiceName: mode === SessionMode.PUBLIC ? 'Puck' : 'Fenrir' 
            } 
          },
        },
        systemInstruction: mode === SessionMode.PUBLIC ? publicPrompt : privatePrompt,
      },
    });
  }

  public async switchMode(mode: SessionMode) {
      await this.connect(mode);
  }

  public async sendText(text: string) {
    if (this.sessionPromise) {
      const session = await this.sessionPromise;
      session.sendClientContent({ turns: [{ role: 'user', parts: [{ text: text }] }] });
    }
  }

  private handleOpen() {
    if (!this.audioContext || !this.stream) return;
    const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    const source = inputAudioContext.createMediaStreamSource(this.stream);
    const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
    scriptProcessor.onaudioprocess = (e) => {
      if (!this.sessionPromise) return;
      const inputData = e.inputBuffer.getChannelData(0);
      const pcmBlob = createPcmBlob(inputData);
      this.sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob })).catch(() => {});
    };
    source.connect(scriptProcessor);
    scriptProcessor.connect(inputAudioContext.destination);
  }

  private async handleMessage(message: LiveServerMessage) {
    if (message.serverContent?.outputTranscription) this.currentOutputTranscript += message.serverContent.outputTranscription.text;
    else if (message.serverContent?.inputTranscription) this.currentInputTranscript += message.serverContent.inputTranscription.text;

    if (message.serverContent?.turnComplete) {
      if (this.currentInputTranscript && this.config.onTranscript) this.config.onTranscript(this.currentInputTranscript, 'user');
      if (this.currentOutputTranscript && this.config.onTranscript) this.config.onTranscript(this.currentOutputTranscript, 'model');
      this.currentOutputTranscript = "";
      this.currentInputTranscript = "";
    }

    const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
    if (base64Audio && this.audioContext && this.outputNode) {
      const audioData = base64ToUint8Array(base64Audio);
      this.nextStartTime = Math.max(this.nextStartTime, this.audioContext.currentTime);
      const audioBuffer = await decodeAudioData(audioData, this.audioContext, 24000, 1);
      const source = this.audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(this.outputNode);
      source.start(this.nextStartTime);
      this.nextStartTime += audioBuffer.duration;
      this.sources.add(source);
    }
  }

  private handleClose() { this.sessionPromise = null; this.config.onClose(); }

  private startVolumeMonitoring() {
    const dataArray = new Uint8Array(this.analyser!.frequencyBinCount);
    this.volumeInterval = window.setInterval(() => {
      this.analyser?.getByteFrequencyData(dataArray);
      let sum = 0; for (let i = 0; i < dataArray.length; i++) sum += dataArray[i];
      this.config.onVolumeChange(sum / dataArray.length);
    }, 50);
  }

  public async disconnect(fullStop: boolean = true) {
    if (this.volumeInterval) clearInterval(this.volumeInterval);
    if (this.sessionPromise) {
      const s = await this.sessionPromise;
      try { s.close(); } catch(e) {}
      this.sessionPromise = null;
    }
    if (fullStop && this.stream) { this.stream.getTracks().forEach(t => t.stop()); this.stream = null; }
    if (fullStop && this.audioContext) { await this.audioContext.close(); this.audioContext = null; }
  }
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Scene from './components/Scene';
import UI from './components/UI';
import { SystemStatus, ChatMessage, SessionMode } from './types';
import { LiveService } from './services/liveService';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [status, setStatus] = useState<SystemStatus>(SystemStatus.OPTIMAL);
  const [mode, setMode] = useState<SessionMode>(SessionMode.PUBLIC);
  const [hasStarted, setHasStarted] = useState(false);
  const [audioVolume, setAudioVolume] = useState(0);
  const [touchCountPublic, setTouchCountPublic] = useState(0);
  const [touchCountPrivate, setTouchCountPrivate] = useState(0);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);

  const [isScanning, setIsScanning] = useState(false);
  const [enhancedImageUrl, setEnhancedImageUrl] = useState<string | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [isVideoGenerating, setIsVideoGenerating] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [videoProgress, setVideoProgress] = useState("");

  const liveServiceRef = useRef<LiveService | null>(null);
  const neuralSynthRef = useRef<AudioContext | null>(null);

  const playNeuralSound = useCallback((mode: SessionMode) => {
    if (!neuralSynthRef.current) {
      neuralSynthRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    const ctx = neuralSynthRef.current;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    if (mode === SessionMode.PUBLIC) {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880 + Math.random() * 220, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(440, ctx.currentTime + 0.1);
    } else {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(110 + Math.random() * 55, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(20, ctx.currentTime + 0.15);
    }

    gain.gain.setValueAtTime(0.08, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.15);
  }, []);

  const handleTouch = useCallback(() => {
    if (mode === SessionMode.PUBLIC) setTouchCountPublic(p => p + 1);
    else setTouchCountPrivate(p => p + 1);
    playNeuralSound(mode);
  }, [mode, playNeuralSound]);

  const addChatMessage = useCallback((text: string, role: 'user' | 'model') => {
    setChatHistory(prev => [...prev, { role, text, timestamp: Date.now(), mode }]);
  }, [mode]);

  const handleStart = async () => {
    try {
      const service = new LiveService({
        onVolumeChange: (vol) => setAudioVolume(vol),
        onClose: () => console.log("Closed"),
        onThreatCancel: () => setMode(SessionMode.PUBLIC),
        onTranscript: (text, role) => addChatMessage(text, role)
      });
      await service.connect(SessionMode.PUBLIC); 
      liveServiceRef.current = service;
      setHasStarted(true);
      setStatus(SystemStatus.OPTIMAL);
    } catch (error) {
      console.error("Start failed", error);
    }
  };

  const handleToggleMode = async () => {
    const newMode = mode === SessionMode.PUBLIC ? SessionMode.PRIVATE : SessionMode.PUBLIC;
    setMode(newMode);
    if (liveServiceRef.current) {
      await liveServiceRef.current.switchMode(newMode);
    }
    playNeuralSound(newMode);
  };

  const handleSendText = async (text: string) => {
    if (liveServiceRef.current) {
      addChatMessage(text, 'user');
      await liveServiceRef.current.sendText(text);
    }
  };

  const handleImageEnhance = async (base64: string) => {
    if (isScanning) return;
    setIsScanning(true);
    setOriginalImageUrl(base64);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ inlineData: { data: base64.split(',')[1], mimeType: 'image/png' } }, { text: 'Enhance this robotic subject.' }] }
      });
      const part = response.candidates[0].content.parts.find(p => p.inlineData);
      if (part) setEnhancedImageUrl(`data:image/png;base64,${part.inlineData.data}`);
    } catch (err) { console.error(err); }
    setIsScanning(false);
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (isVideoGenerating) return;
    setIsVideoGenerating(true);
    setVideoProgress("Compiling cinematic layers...");
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let op = await ai.models.generateVideos({ model: 'veo-3.1-fast-generate-preview', prompt });
      while (!op.done) {
        await new Promise(r => setTimeout(r, 10000));
        op = await ai.operations.getVideosOperation({ operation: op });
      }
      const link = op.response?.generatedVideos?.[0]?.video?.uri;
      if (link) {
        const res = await fetch(`${link}&key=${process.env.API_KEY}`);
        setVideoUrl(URL.createObjectURL(await res.blob()));
      }
    } catch (err) { console.error(err); }
    setIsVideoGenerating(false);
  };

  return (
    <div className="w-full h-screen bg-[#0c0018] overflow-hidden select-none">
      <Scene status={status} mode={mode} audioVolume={audioVolume} onTouch={handleTouch} />
      <UI 
        status={status} mode={mode} onStart={handleStart} hasStarted={hasStarted} 
        onSendText={handleSendText} onToggleMode={handleToggleMode}
        onImageUpload={handleImageEnhance} isScanning={isScanning}
        originalImage={originalImageUrl} enhancedImage={enhancedImageUrl}
        onVideoGenerate={handleGenerateVideo} isVideoGenerating={isVideoGenerating}
        videoProgress={videoProgress} videoUrl={videoUrl}
        chatHistory={chatHistory} 
        touchCountPublic={touchCountPublic}
        touchCountPrivate={touchCountPrivate}
      />
    </div>
  );
};
export default App;

import React, { useEffect, useRef, useMemo } from 'react';
import * as THREE from 'three';
import { SystemStatus, SessionMode } from '../types';

interface SceneProps {
  status: SystemStatus;
  mode: SessionMode;
  audioVolume: number;
  onTouch: () => void;
}

const vertexShader = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uIntensity;
  varying vec2 vUv;
  void main() {
    vec2 uv = vUv;
    float t = uTime * 0.2;
    for(float i = 1.0; i < 5.0; i++){
        uv.x += 0.3 / i * cos(i * 3.0 * uv.y + t);
        uv.y += 0.3 / i * cos(i * 2.0 * uv.x + t);
    }
    float strength = 0.5 + 0.5 * sin(uv.x * 12.0 + uTime);
    vec3 color = mix(uColorA, uColorB, strength * uIntensity);
    float dist = distance(vUv, vec2(0.5));
    color *= 1.2 - dist * 1.1;
    gl_FragColor = vec4(color, 1.0);
  }
`;

const Scene: React.FC<SceneProps> = ({ status, mode, audioVolume, onTouch }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const backgroundMaterialRef = useRef<THREE.ShaderMaterial | null>(null);
  const interactionLightRef = useRef<THREE.PointLight | null>(null);
  const roboEchoGroupRef = useRef<THREE.Group | null>(null);
  const roboVigilGroupRef = useRef<THREE.Group | null>(null);
  const airParticlesRef = useRef<THREE.Points | null>(null);
  const animationFrameRef = useRef<number>(0);
  const raycaster = useMemo(() => new THREE.Raycaster(), []);
  const mouse = useMemo(() => new THREE.Vector2(), []);

  const themes = useMemo(() => ({
    [SessionMode.PUBLIC]: { a: new THREE.Color('#05000a'), b: new THREE.Color('#4e36e0'), air: new THREE.Color('#ffffff') },
    [SessionMode.PRIVATE]: { a: new THREE.Color('#0a0000'), b: new THREE.Color('#ff0000'), air: new THREE.Color('#ff4444') }
  }), []);

  useEffect(() => {
    if (!mountRef.current) return;
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    const camera = new THREE.PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 20;
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const bgMat = new THREE.ShaderMaterial({
      vertexShader, fragmentShader,
      uniforms: { uTime: { value: 0 }, uColorA: { value: themes[mode].a }, uColorB: { value: themes[mode].b }, uIntensity: { value: 0.6 } },
      depthWrite: false, 
    });
    const bg = new THREE.Mesh(new THREE.PlaneGeometry(120, 120), bgMat);
    bg.position.z = -25;
    scene.add(bg);
    backgroundMaterialRef.current = bgMat;

    const interactionLight = new THREE.PointLight(0xffffff, 0, 50);
    scene.add(interactionLight);
    interactionLightRef.current = interactionLight;

    // Robots
    const echoGroup = new THREE.Group();
    echoGroup.add(new THREE.Mesh(new THREE.SphereGeometry(2.4, 64, 64), new THREE.MeshPhysicalMaterial({ color: 0x5a47e7, emissive: 0x5a47e7, emissiveIntensity: 3, roughness: 0.1, metalness: 0.9 })));
    scene.add(echoGroup);
    roboEchoGroupRef.current = echoGroup;

    const vigilGroup = new THREE.Group();
    vigilGroup.add(new THREE.Mesh(new THREE.IcosahedronGeometry(3.2, 0), new THREE.MeshStandardMaterial({ color: 0x000000, emissive: 0xff0000, emissiveIntensity: 10 })));
    vigilGroup.visible = false;
    scene.add(vigilGroup);
    roboVigilGroupRef.current = vigilGroup;

    // Air
    const airGeo = new THREE.BufferGeometry();
    const airPos = new Float32Array(1500 * 3);
    for(let i=0; i<4500; i++) airPos[i] = (Math.random() - 0.5) * 40;
    airGeo.setAttribute('position', new THREE.BufferAttribute(airPos, 3));
    const airPoints = new THREE.Points(airGeo, new THREE.PointsMaterial({ size: 0.05, transparent: true, opacity: 0.3 }));
    scene.add(airPoints);
    airParticlesRef.current = airPoints;

    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);
      const time = Date.now() * 0.001;
      const vol = audioVolume / 100;

      bgMat.uniforms.uTime.value += 0.005 + vol * 0.02;
      bgMat.uniforms.uColorA.value.lerp(themes[mode].a, 0.05);
      bgMat.uniforms.uColorB.value.lerp(themes[mode].b, 0.05);

      if (airParticlesRef.current) {
          const mat = airParticlesRef.current.material as THREE.PointsMaterial;
          mat.color.lerp(themes[mode].air, 0.1);
          const pos = airParticlesRef.current.geometry.attributes.position.array as Float32Array;
          const drift = mode === SessionMode.PRIVATE ? 0.04 : 0.01;
          for(let i=0; i<pos.length/3; i++){
            pos[i*3] += Math.sin(time + i) * drift;
            pos[i*3+1] += Math.cos(time + i) * drift;
          }
          airParticlesRef.current.geometry.attributes.position.needsUpdate = true;
      }

      roboEchoGroupRef.current!.visible = mode === SessionMode.PUBLIC;
      roboVigilGroupRef.current!.visible = mode === SessionMode.PRIVATE;
      const activeBot = mode === SessionMode.PUBLIC ? roboEchoGroupRef.current : roboVigilGroupRef.current;
      if (activeBot) activeBot.rotation.y += 0.01 + vol * 0.1;

      renderer.render(scene, camera);
    };
    animate();

    const onDown = (e: MouseEvent) => {
      mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
      mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
      raycaster.setFromCamera(mouse, camera);
      const hits = raycaster.intersectObjects([roboEchoGroupRef.current!, roboVigilGroupRef.current!], true);
      if (hits.length > 0) {
        onTouch();
        interactionLight.position.copy(hits[0].point);
        interactionLight.intensity = 20;
        setTimeout(() => interactionLight.intensity = 0, 100);
      }
    };
    window.addEventListener('mousedown', onDown);
    return () => { cancelAnimationFrame(animationFrameRef.current); window.removeEventListener('mousedown', onDown); renderer.dispose(); };
  }, [mode, themes, audioVolume, onTouch, mouse, raycaster]);

  return <div ref={mountRef} className="fixed inset-0" />;
};
export default Scene;

