import React, { useEffect, useRef, useMemo } from 'react';
import * as THREE from 'three';
import { SystemStatus, SessionMode } from '../types';

interface SceneProps {
  status: SystemStatus;
  mode: SessionMode;
  audioVolume: number;
  onTouch: () => void;
}

const vertexShader = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uIntensity;
  varying vec2 vUv;
  void main() {
    vec2 uv = vUv;
    float t = uTime * 0.2;
    for(float i = 1.0; i < 5.0; i++){
        uv.x += 0.3 / i * cos(i * 3.0 * uv.y + t);
        uv.y += 0.3 / i * cos(i * 2.0 * uv.x + t);
    }
    float strength = 0.5 + 0.5 * sin(uv.x * 12.0 + uTime);
    vec3 color = mix(uColorA, uColorB, strength * uIntensity);
    float dist = distance(vUv, vec2(0.5));
    color *= 1.2 - dist * 1.1;
    gl_FragColor = vec4(color, 1.0);
  }
`;

const Scene: React.FC<SceneProps> = ({ status, mode, audioVolume, onTouch }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const backgroundMaterialRef = useRef<THREE.ShaderMaterial | null>(null);
  const roboEchoGroupRef = useRef<THREE.Group | null>(null);
  const roboVigilGroupRef = useRef<THREE.Group | null>(null);
  const radioWavesGroupRef = useRef<THREE.Group | null>(null);
  const lasersGroupRef = useRef<THREE.Group | null>(null);
  const airParticlesRef = useRef<THREE.Points | null>(null);
  const animationFrameRef = useRef<number>(0);
  const raycaster = useMemo(() => new THREE.Raycaster(), []);
  const mouse = useMemo(() => new THREE.Vector2(), []);

  const themes = useMemo(() => ({
    [SessionMode.PUBLIC]: { a: new THREE.Color('#05000a'), b: new THREE.Color('#4e36e0'), air: new THREE.Color('#ffffff'), wave: new THREE.Color('#5a47e7'), laser: new THREE.Color('#00ffff') },
    [SessionMode.PRIVATE]: { a: new THREE.Color('#0a0000'), b: new THREE.Color('#ff0000'), air: new THREE.Color('#ff4444'), wave: new THREE.Color('#ff0000'), laser: new THREE.Color('#ff0000') }
  }), []);

  useEffect(() => {
    if (!mountRef.current) return;
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    const camera = new THREE.PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 20;
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const bgMat = new THREE.ShaderMaterial({
      vertexShader, fragmentShader,
      uniforms: { uTime: { value: 0 }, uColorA: { value: themes[mode].a }, uColorB: { value: themes[mode].b }, uIntensity: { value: 0.6 } },
      depthWrite: false, 
    });
    const bg = new THREE.Mesh(new THREE.PlaneGeometry(120, 120), bgMat);
    bg.position.z = -25;
    scene.add(bg);
    backgroundMaterialRef.current = bgMat;

    // Laser Beams Group
    const lasers = new THREE.Group();
    const laserCount = 12;
    for (let i = 0; i < laserCount; i++) {
      const laserGeo = new THREE.CylinderGeometry(0.02, 0.02, 100, 8);
      const laserMat = new THREE.MeshBasicMaterial({
        color: themes[mode].laser,
        transparent: true,
        opacity: 0.5,
        blending: THREE.AdditiveBlending,
      });
      const laser = new THREE.Mesh(laserGeo, laserMat);

      // Random initial orientation
      laser.rotation.x = Math.random() * Math.PI;
      laser.rotation.z = Math.random() * Math.PI;
      laser.userData = { 
        speed: 0.2 + Math.random() * 0.5,
        axis: new THREE.Vector3(Math.random(), Math.random(), Math.random()).normalize()
      };
      lasers.add(laser);
    }
    scene.add(lasers);
    lasersGroupRef.current = lasers;

    // Radio Waves Group
    const radioWaves = new THREE.Group();
    const waveCount = 5;
    for (let i = 0; i < waveCount; i++) {
      const ringGeo = new THREE.RingGeometry(1, 1.05, 64);
      const ringMat = new THREE.MeshBasicMaterial({ 
        color: themes[mode].wave, 
        transparent: true, 
        opacity: 0, 
        side: THREE.DoubleSide 
      });
      const ring = new THREE.Mesh(ringGeo, ringMat);
      ring.userData = { offset: i / waveCount };
      radioWaves.add(ring);
    }
    scene.add(radioWaves);
    radioWavesGroupRef.current = radioWaves;

    // Robots
    const echoGroup = new THREE.Group();
    echoGroup.add(new THREE.Mesh(new THREE.SphereGeometry(2.4, 64, 64), new THREE.MeshPhysicalMaterial({ color: 0x5a47e7, emissive: 0x5a47e7, emissiveIntensity: 3, roughness: 0.1, metalness: 0.9 })));
    scene.add(echoGroup);
    roboEchoGroupRef.current = echoGroup;

    const vigilGroup = new THREE.Group();
    vigilGroup.add(new THREE.Mesh(new THREE.IcosahedronGeometry(3.2, 0), new THREE.MeshStandardMaterial({ color: 0x000000, emissive: 0xff0000, emissiveIntensity: 10 })));
    vigilGroup.visible = false;
    scene.add(vigilGroup);
    roboVigilGroupRef.current = vigilGroup;

    // Air Particles
    const airGeo = new THREE.BufferGeometry();
    const airPos = new Float32Array(1500 * 3);
    for(let i=0; i<4500; i++) airPos[i] = (Math.random() - 0.5) * 40;
    airGeo.setAttribute('position', new THREE.BufferAttribute(airPos, 3));
    const airPoints = new THREE.Points(airGeo, new THREE.PointsMaterial({ size: 0.05, transparent: true, opacity: 0.3 }));
    scene.add(airPoints);
    airParticlesRef.current = airPoints;

    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);
      const time = Date.now() * 0.001;
      const vol = audioVolume / 100;

      bgMat.uniforms.uTime.value += 0.005 + vol * 0.05;
      bgMat.uniforms.uColorA.value.lerp(themes[mode].a, 0.05);
      bgMat.uniforms.uColorB.value.lerp(themes[mode].b, 0.05);

      // Update Lasers
      lasers.children.forEach((child, idx) => {
        const laser = child as THREE.Mesh;
        const mat = laser.material as THREE.MeshBasicMaterial;
        mat.color.lerp(themes[mode].laser, 0.1);

        const modeSpeed = mode === SessionMode.PRIVATE ? 4 : 1;
        const jitter = mode === SessionMode.PRIVATE ? Math.sin(time * 20 + idx) * 0.1 : 0;

        laser.rotateOnAxis(laser.userData.axis, 0.002 * modeSpeed + vol * 0.05 + jitter);

        // Intensity flickering
        const flick = Math.random() > 0.9 ? 1.0 : 0.4;
        mat.opacity = (0.3 + vol * 0.7) * flick;
      });

      // Update Radio Waves
      radioWaves.children.forEach((child) => {
        const mesh = child as THREE.Mesh;
        const mat = mesh.material as THREE.MeshBasicMaterial;
        mat.color.lerp(themes[mode].wave, 0.1);

        let progress = (time * (0.3 + vol) + mesh.userData.offset) % 1.0;
        const scale = 1 + progress * 25;
        mesh.scale.set(scale, scale, scale);
        mat.opacity = (1.0 - progress) * (0.2 + vol * 0.8);
      });

      if (airParticlesRef.current) {
          const mat = airParticlesRef.current.material as THREE.PointsMaterial;
          mat.color.lerp(themes[mode].air, 0.1);
          const pos = airParticlesRef.current.geometry.attributes.position.array as Float32Array;
          const drift = mode === SessionMode.PRIVATE ? 0.04 : 0.01;
          for(let i=0; i<pos.length/3; i++){
            pos[i*3] += Math.sin(time + i) * drift;
            pos[i*3+1] += Math.cos(time + i) * drift;
          }
          airParticlesRef.current.geometry.attributes.position.needsUpdate = true;
      }

      roboEchoGroupRef.current!.visible = mode === SessionMode.PUBLIC;
      roboVigilGroupRef.current!.visible = mode === SessionMode.PRIVATE;
      const activeBot = mode === SessionMode.PUBLIC ? roboEchoGroupRef.current : roboVigilGroupRef.current;
      if (activeBot) {
        activeBot.rotation.y += 0.01 + vol * 0.2;
        activeBot.position.y = Math.sin(time) * 0.5;
        radioWaves.position.copy(activeBot.position);
        lasers.position.copy(activeBot.position);
      }

      renderer.render(scene, camera);
    };
    animate();

    const onDown = (e: MouseEvent) => {
      mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
      mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
      raycaster.setFromCamera(mouse, camera);
      const hits = raycaster.intersectObjects([roboEchoGroupRef.current!, roboVigilGroupRef.current!], true);
      if (hits.length > 0) onTouch();
    };
    window.addEventListener('mousedown', onDown);

    const onResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };
    window.addEventListener('resize', onResize);

    return () => { 
      cancelAnimationFrame(animationFrameRef.current); 
      window.removeEventListener('mousedown', onDown); 
      window.removeEventListener('resize', onResize);
      renderer.dispose(); 
    };
  }, [mode, themes, audioVolume, onTouch]);

  return <div ref={mountRef} className="fixed inset-0" />;
};
export default Scene;

import React, { useEffect, useState, useRef, useMemo } from 'react';
import { SystemStatus, ChatMessage, SessionMode } from '../types';

interface UIProps {
  status: SystemStatus;
  mode: SessionMode;
  onStart: () => void;
  hasStarted: boolean;
  onSendText: (text: string) => void;
  onToggleMode: () => void;
  onImageUpload: (base64: string) => void;
  chatHistory?: ChatMessage[];
  touchCountPublic: number;
  touchCountPrivate: number;
  isOnline: boolean;
  audioVolume: number;
}

const UI: React.FC<UIProps> = ({ 
    status, mode, onStart, hasStarted, onSendText, onToggleMode, 
    onImageUpload, chatHistory = [], touchCountPublic, touchCountPrivate, isOnline, audioVolume
}) => {
  const [inputText, setInputText] = useState("");
  const chatScrollRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const radarRef = useRef<HTMLCanvasElement>(null);
  const isPrivate = mode === SessionMode.PRIVATE;

  const color = isPrivate ? '#ff0000' : '#5a47e7';
  const frequency = isPrivate ? '104.9 MHz' : '88.4 MHz';

  useEffect(() => {
    if (chatScrollRef.current) chatScrollRef.current.scrollTop = chatScrollRef.current.scrollHeight;
  }, [chatHistory]);

  // Frequency Oscilloscope
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !hasStarted) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.lineWidth = 2;
      ctx.strokeStyle = color;

      const sliceWidth = canvas.width / 50;
      let x = 0;

      for (let i = 0; i < 50; i++) {
        const v = (audioVolume / 128.0) * (Math.random() * 20 + 10);
        const y = canvas.height / 2 + (i % 2 === 0 ? v : -v);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
        x += sliceWidth;
      }

      ctx.stroke();
      animId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animId);
  }, [hasStarted, audioVolume, color]);

  // Neural Radar Sweep
  useEffect(() => {
    const canvas = radarRef.current;
    if (!canvas || !hasStarted) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let angle = 0;
    let animId: number;

    const drawRadar = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      const r = canvas.width / 2 - 5;

      // Circles
      ctx.strokeStyle = `${color}44`;
      ctx.lineWidth = 1;
      for (let i = 1; i <= 3; i++) {
        ctx.beginPath();
        ctx.arc(cx, cy, (r / 3) * i, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Sweep
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, r, angle, angle + 0.2);
      ctx.lineTo(cx, cy);
      const gradient = ctx.createConicGradient(angle, cx, cy);
      gradient.addColorStop(0, `${color}00`);
      gradient.addColorStop(0.2, `${color}88`);
      ctx.fillStyle = gradient;
      ctx.fill();

      // Blips (Hits)
      const hitCount = isPrivate ? touchCountPrivate : touchCountPublic;
      if (hitCount > 0) {
        ctx.fillStyle = color;
        for (let i = 0; i < (hitCount % 5) + 1; i++) {
           const bX = cx + Math.cos(i * 2) * (r * 0.6);
           const bY = cy + Math.sin(i * 2) * (r * 0.6);
           ctx.beginPath();
           ctx.arc(bX, bY, 3, 0, Math.PI * 2);
           ctx.fill();
        }
      }

      angle += 0.03;
      animId = requestAnimationFrame(drawRadar);
    };
    drawRadar();
    return () => cancelAnimationFrame(animId);
  }, [hasStarted, color, isPrivate, touchCountPublic, touchCountPrivate]);

  if (!hasStarted) {
    return (
      <div className="fixed inset-0 bg-[#050008] z-[200] flex items-center justify-center p-6">
        <div className="border border-[#5a47e7] p-12 text-center max-w-lg w-full bg-black/80 backdrop-blur-3xl shadow-[0_0_50px_rgba(90,71,231,0.2)]">
          <h1 className="text-5xl font-bold mb-2 tracking-[0.5em] text-white font-['Orbitron'] uppercase">VANHSYA</h1>
          <div className="h-px w-full bg-[#5a47e7]/30 my-6"></div>
          <p className="text-[10px] text-[#5a47e7] font-mono mb-8 tracking-[0.3em] uppercase leading-loose">
            Neural Radio Transmission Interface<br/>
            Secure Encryption: {isOnline ? "AES-256 CLOUD" : "LOCAL AIR-GAP"}<br/>
            Status: Standby...
          </p>
          <button onClick={onStart} className="group relative w-full overflow-hidden py-5 border border-[#5a47e7] text-[#5a47e7] font-bold tracking-[0.4em] uppercase transition-all hover:bg-[#5a47e7] hover:text-white">
            <span className="relative z-10">Engage Neural Link</span>
            <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={`fixed inset-0 pointer-events-none z-[110] transition-colors duration-1000 ${isPrivate ? 'bg-red-500/5' : 'bg-blue-500/5'}`}>

      {/* Top Banner - Tactical HUD */}
      <div className="absolute top-6 left-6 right-6 flex justify-between items-start">
        <div className="flex flex-col gap-2">
           <div className={`border p-3 px-5 rounded-sm backdrop-blur-md font-mono text-xs tracking-widest uppercase transition-all flex items-center gap-4 ${isPrivate ? 'border-red-500 text-red-500 bg-red-950/40' : 'border-[#5a47e7] text-[#5a47e7] bg-black/40'}`}>
              <div className="flex flex-col">
                <span className="text-[8px] opacity-60">Frequency</span>
                <span className="font-bold text-lg font-['Orbitron']">{frequency}</span>
              </div>
              <div className="w-px h-10 bg-current opacity-20 mx-2"></div>
              <div className="flex flex-col">
                <span className="text-[8px] opacity-60">Mode</span>
                <span className="font-bold text-sm tracking-tighter">{isPrivate ? 'VIGIL_PRI' : 'ECHO_PUB'}</span>
              </div>

              {/* Pulsating Wave Icon */}
              <div className="flex items-center ml-2 relative w-6 h-6">
                {[1, 2, 3].map(i => (
                  <div 
                    key={i} 
                    className="absolute inset-0 border-2 rounded-full animate-ping opacity-50"
                    style={{ borderColor: color, animationDuration: `${1 / (1 + audioVolume/50)}s`, animationDelay: `${i * 0.2}s` }}
                  />
                ))}
              </div>

              {!isOnline && <span className="ml-4 px-2 py-1 bg-yellow-500 text-black font-black text-[9px] rounded-sm">OFFLINE</span>}
           </div>

           <button onClick={onToggleMode} className={`pointer-events-auto border p-2 px-6 font-mono text-[9px] uppercase tracking-[0.3em] transition-all flex items-center gap-2 hover:scale-105 active:scale-95 ${isPrivate ? 'bg-red-500 text-black border-red-500' : 'bg-[#5a47e7] text-white border-[#5a47e7]'}`}>
              <div className="w-2 h-2 rounded-full bg-current animate-ping"></div>
              Relink Channel
           </button>
        </div>

        <div className="flex flex-col items-end gap-2 text-[10px] font-mono uppercase tracking-widest">
            <div className="flex gap-4 p-2 bg-black/40 border border-white/10 rounded">
                <div className="flex flex-col items-end">
                    <span className="text-[#5a47e7] text-[8px]">ECHO_SYNC</span>
                    <span className="text-white text-lg font-['Orbitron']">{touchCountPublic.toString().padStart(4, '0')}</span>
                </div>
                <div className="flex flex-col items-end">
                    <span className="text-red-500 text-[8px]">VIGIL_SYNC</span>
                    <span className="text-red-500 text-lg font-['Orbitron']">{touchCountPrivate.toString().padStart(4, '0')}</span>
                </div>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex flex-col items-end">
                <span className="text-[8px] opacity-50">LASER_GRID</span>
                <div className={`w-3 h-3 rounded-full ${audioVolume > 20 ? 'bg-white shadow-[0_0_10px_white]' : 'bg-white/20'} transition-all`}></div>
              </div>
              <div className="flex flex-col items-end">
                  <span className="opacity-50">Signal Gain</span>
                  <div className="flex gap-1 h-3 items-end">
                      {[1, 2, 3, 4, 5].map(i => (
                          <div key={i} className={`w-1 bg-current ${i <= (isOnline ? 5 : 2) ? 'opacity-100' : 'opacity-20'}`} style={{ height: `${i * 20}%`, opacity: audioVolume > 5 ? Math.random() : 1 }}></div>
                      ))}
                  </div>
              </div>
            </div>
        </div>
      </div>

      {/* Neural Chat Stream */}
      <div className="absolute top-48 left-6 bottom-40 w-80 pointer-events-auto">
        <div className={`h-full border backdrop-blur-xl flex flex-col overflow-hidden transition-all shadow-2xl ${isPrivate ? 'border-red-500/40 bg-red-950/30' : 'border-[#5a47e7]/40 bg-black/40'}`}>
          <div className="p-3 border-b border-inherit bg-black/20 flex justify-between items-center">
             <span className="text-[10px] font-mono font-bold uppercase tracking-widest opacity-70">Neural Logs</span>
             <div className="flex gap-1">
                <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
                <div className="w-1.5 h-1.5 rounded-full bg-green-500/50 animate-pulse delay-75"></div>
                <div className="w-1.5 h-1.5 rounded-full bg-green-500/20 animate-pulse delay-150"></div>
             </div>
          </div>
          <div ref={chatScrollRef} className="flex-grow overflow-y-auto p-4 space-y-4 no-scrollbar scroll-smooth">
            {chatHistory.map((msg, i) => (
              <div key={i} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                <div className={`text-[8px] font-mono mb-1 uppercase opacity-50 flex gap-2 ${msg.mode === SessionMode.PRIVATE ? 'text-red-400' : 'text-blue-400'}`}>
                   {msg.role === 'user' ? 'Operator' : (msg.mode === SessionMode.PRIVATE ? 'Vigil_7' : 'Echo_3')}
                </div>
                <div className={`max-w-[95%] px-3 py-2 text-[11px] font-mono border leading-relaxed shadow-sm transition-all ${msg.role === 'user' ? 'border-white/20 text-white bg-white/5 italic' : (msg.mode === SessionMode.PRIVATE ? 'border-red-500/40 text-red-200 bg-red-950/40' : 'border-[#5a47e7]/40 text-blue-200 bg-[#5a47e7]/10')}`}>
                  {msg.text}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Bottom Command Center */}
      <div className="absolute bottom-6 left-6 right-6 flex items-end gap-6 pointer-events-auto">
         {/* Oscilloscope */}
         <div className="flex-grow max-w-sm hidden md:block">
            <div className="mb-2 text-[9px] font-mono opacity-50 uppercase tracking-[0.2em] flex items-center gap-2">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm-1-13h2v6h-2zm0 8h2v2h-2z"/></svg>
              Broadcasting Waveform
            </div>
            <canvas ref={canvasRef} width={400} height={60} className="w-full h-15 border border-white/5 bg-black/30 rounded-sm" />
         </div>

         {/* Command Input */}
         <div className="flex-grow max-w-3xl">
            <form onSubmit={(e) => { e.preventDefault(); if(inputText.trim()){ onSendText(inputText); setInputText(""); }}} className="relative flex group">
               <div className="absolute -top-6 left-0 text-[8px] font-mono uppercase tracking-widest opacity-40">Command Uplink Channel 01</div>
               <input 
                 value={inputText} 
                 onChange={e => setInputText(e.target.value)} 
                 placeholder={`Tuning input for ${isPrivate ? 'VIGIL' : 'ECHO'}...`} 
                 className={`w-full border font-mono p-4 px-6 focus:outline-none transition-all text-sm tracking-wider ${isPrivate ? 'bg-red-950/40 border-red-500/50 text-red-400 placeholder:text-red-900' : 'bg-black/80 border-[#5a47e7]/50 text-[#5a47e7] placeholder:text-[#5a47e7]/40'}`} 
               />
               <button type="submit" className={`border-y border-r px-10 font-black font-['Orbitron'] text-xs tracking-[0.2em] transition-all hover:brightness-125 ${isPrivate ? 'bg-red-600 text-black border-red-500' : 'bg-[#5a47e7] text-white border-[#5a47e7]'}`}>
                  SEND
               </button>
            </form>
         </div>

         {/* Radar Array */}
         <div className="hidden lg:block relative">
            <div className="mb-2 text-right text-[9px] font-mono opacity-50 uppercase tracking-[0.2em]">Neural Radar Array</div>
            <canvas ref={radarRef} width={120} height={120} className="rounded-full border border-white/5 bg-black/40 p-1" />
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
              <div className="w-16 h-16 border border-current rounded-full animate-ping" style={{ color }}></div>
            </div>
         </div>
      </div>

      {/* Right Utility Bar */}
      <div className="absolute top-48 right-6 w-12 flex flex-col gap-4 pointer-events-auto">
          <input type="file" onChange={(e) => { const f = e.target.files?.[0]; if(f){ const r = new FileReader(); r.onload = (ev) => onImageUpload(ev.target?.result as string); r.readAsDataURL(f); }}} className="hidden" id="asset-up" />
          <label htmlFor="asset-up" className={`w-12 h-12 flex items-center justify-center border cursor-pointer hover:bg-white/5 transition-all ${isPrivate ? 'border-red-500/50 text-red-500' : 'border-[#5a47e7]/50 text-[#5a47e7]'}`}>
             <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg>
          </label>
      </div>

      <style>{`.no-scrollbar::-webkit-scrollbar { display: none; }`}</style>
    </div>
  );
};
export default UI;
